export default "\r\n    var rawData = [], userList = [], usuariosPorEmail = new Map(), categorias = [], notasData = {}, currentTab = 'gestion', mEntry, mNota, mKanbanDetail, mAtraso, mGeneral, currentUserEmail = \"\", hasProjects = false;\r\n    var ckEditor = null, ckNota = null, ckGeneralAlerta = null, ckGeneralBloq = null, ckGeneralNota = null;\r\n    var proyectosData = [], asignacionesData = [];\r\n    var draggedAvanceId = null, isDraggingPostit = false;\r\n\r\n    const CK_CONFIG = {\r\n        language: 'es',\r\n        toolbar: ['bold', 'italic', 'underline', '|', 'bulletedList', 'numberedList', '|', 'link', '|', 'undo', 'redo'],\r\n        link: { defaultProtocol: 'https://', addTargetToExternalLinks: true }\r\n    };\r\n\r\n    const ESTADO_COLORIMETRIA = {\r\n        'No iniciado':         { hex: '#8C8C8C', bgSoft: '#fafafa', textDark: '#595959', icon: '⚪', label: 'No iniciado',         cssClass: 'st-pending' },\r\n        'En proceso':          { hex: '#1890FF', bgSoft: '#e6f7ff', textDark: '#0050b3', icon: '🔵', label: 'En proceso',          cssClass: 'st-process' },\r\n        'Detenido_Alerta':     { hex: '#FAAD14', bgSoft: '#fffbe6', textDark: '#ad6800', icon: '🟡', label: 'Detenido (Alerta)',   cssClass: 'st-pause' },\r\n        'Detenido_Bloqueante': { hex: '#FF4D4F', bgSoft: '#fff1f0', textDark: '#cf1322', icon: '🔴', label: 'Detenido (Bloqueo)',  cssClass: 'st-block' },\r\n        'Detenido':            { hex: '#FAAD14', bgSoft: '#fffbe6', textDark: '#ad6800', icon: '🛑', label: 'Detenido',            cssClass: 'st-pause' },\r\n        'Completado':          { hex: '#52C41A', bgSoft: '#f6ffed', textDark: '#237804', icon: '🟢', label: 'Completado',          cssClass: 'st-done' }\r\n    };\r\n\r\n    const TAB_INFO_MAP = {\r\n        'gestion': {\r\n            icon: '<i class=\"bi bi-layers\"></i>',\r\n            title: 'Vista de Tareas Activas',\r\n            desc: 'Registra y administra el trabajo diario en curso (Tareas, Subtareas y Actividades no iniciadas, en proceso o detenidas). Los elementos marcados como Completados se archivan automáticamente en el Reporte Histórico.'\r\n        },\r\n        'reporte': {\r\n            icon: '<i class=\"bi bi-clock-history\"></i>',\r\n            title: 'Vista de Reporte Histórico',\r\n            desc: 'Consulta el historial completo de actividades activas y completadas, filtra por rangos de fechas, condiciones o estados, y genera el resumen ejecutivo listo para copiar y enviar por correo.'\r\n        },\r\n        'estado': {\r\n            icon: '<i class=\"bi bi-kanban\"></i>',\r\n            title: 'Vista de Tablero Kanban',\r\n            desc: 'Visualiza las actividades agrupadas por Tarea y Subtarea dentro de cada columna de estado. Arrastra cualquier actividad activa para actualizar su estado (las actividades Completadas quedan fijas por estar finalizadas).'\r\n        }\r\n    };\r\n\r\n    function obtenerInfoColorEstado(estado, itemObj) {\r\n        if (estado === 'Detenido' && itemObj) {\r\n            if (tieneContenidoHtml(itemObj.bloqueante)) return ESTADO_COLORIMETRIA['Detenido_Bloqueante'];\r\n            if (tieneContenidoHtml(itemObj.alerta))     return ESTADO_COLORIMETRIA['Detenido_Alerta'];\r\n            return ESTADO_COLORIMETRIA['Detenido'];\r\n        }\r\n        return ESTADO_COLORIMETRIA[estado] || ESTADO_COLORIMETRIA['En proceso'];\r\n    }\r\n\r\n    function obtenerLabelEstadoReporte(estado, itemObj) {\r\n        if (estado === 'Detenido' && itemObj) {\r\n            if (tieneContenidoHtml(itemObj.bloqueante)) return 'Detenido - Bloqueante';\r\n            if (tieneContenidoHtml(itemObj.alerta))     return 'Detenido - Alerta';\r\n        }\r\n        return estado;\r\n    }\r\n\r\n    function renderBadgeEstadoHtml(estado, itemObj) {\r\n        const info = obtenerInfoColorEstado(estado, itemObj);\r\n        return `<span class=\"badge-opt ${info.cssClass}\" style=\"background:${info.hex};color:#ffffff;\">${info.icon} ${info.label}</span>`;\r\n    }\r\n\r\n    function renderRazonDetenidoDebajoAvanceHtml(av) {\r\n        if (av.estado !== 'Detenido') return '';\r\n        if (tieneContenidoHtml(av.bloqueante)) {\r\n            return `<div class=\"avance-razon-detenido avance-razon-bloqueante\"><strong>🔴 Bloqueante:</strong> ${av.bloqueante}</div>`;\r\n        }\r\n        if (tieneContenidoHtml(av.alerta)) {\r\n            return `<div class=\"avance-razon-detenido avance-razon-alerta\"><strong>⚠️ Alerta:</strong> ${av.alerta}</div>`;\r\n        }\r\n        return '';\r\n    }\r\n\r\n    function nombreDeEmail(emailStr) {\r\n        if (!emailStr) return '—';\r\n        const email = String(emailStr).toLowerCase();\r\n        const usuario = usuariosPorEmail.get(email);\r\n        if (usuario?.nombre) return usuario.nombre;\r\n        return String(emailStr).split('@')[0] || '—';\r\n    }\r\n\r\n    function obtenerInicialesEmail(emailStr) {\r\n        if (!emailStr) return 'U';\r\n        const nombre = nombreDeEmail(emailStr);\r\n        const segmentos = nombre.split(/\\s+/).filter(Boolean);\r\n        if (segmentos.length >= 2) {\r\n            return (segmentos[0][0] + segmentos[1][0]).toUpperCase();\r\n        }\r\n        const parte = nombre.split(/[._-]/).filter(Boolean);\r\n        if (parte.length >= 2) return (parte[0][0] + parte[1][0]).toUpperCase();\r\n        return nombre.substring(0, 2).toUpperCase();\r\n    }\r\n\r\n    function limpiarTextoAttr(htmlStr, maxLen = 40) {\r\n        if (!htmlStr) return '';\r\n        return String(htmlStr)\r\n            .replace(/<[^>]*>/g, '')\r\n            .replace(/\\s+/g, ' ')\r\n            .trim()\r\n            .substring(0, maxLen)\r\n            .replace(/\\\\/g, '\\\\\\\\')\r\n            .replace(/'/g, \"\\\\'\")\r\n            .replace(/\"/g, '&quot;');\r\n    }\r\n\r\n    function textoPlano(htmlStr) {\r\n        if (!htmlStr) return '';\r\n        return String(htmlStr).replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\\s+/g, ' ').trim();\r\n    }\r\n\r\n    function tieneContenidoHtml(htmlStr) {\r\n        return textoPlano(htmlStr).length > 0;\r\n    }\r\n\r\n    function formatearEnlaceOTexto(valor) {\r\n        if (!valor || !String(valor).trim()) return '-';\r\n        const v = String(valor).trim();\r\n        if (/^https?:\\/\\//i.test(v)) {\r\n            return `<a href=\"${v}\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"fw-bold text-break\" style=\"color:#1890FF;\"><i class=\"bi bi-box-arrow-up-right me-1\"></i>Abrir enlace (${v})</a>`;\r\n        }\r\n        return `<span class=\"text-break\">${v}</span>`;\r\n    }\r\n\r\n    function obtenerColaboradoresProyectoActual(projIdParam) {\r\n        const projId = projIdParam || document.getElementById('projSelect').value;\r\n        return asignacionesData\r\n            .filter(a => String(a.proyectoId) === String(projId) && a.email)\r\n            .map(a => a.email.trim().toLowerCase())\r\n            .filter(Boolean)\r\n            .sort();\r\n    }\r\n\r\n    function esLiderProyectoActual(projIdParam) {\r\n        const projId = projIdParam || document.getElementById('projSelect').value;\r\n        return asignacionesData.some(a =>\r\n            String(a.proyectoId) === String(projId) &&\r\n            String(a.email).toLowerCase() === currentUserEmail &&\r\n            a.rol === 'Líder'\r\n        );\r\n    }\r\n\r\n    function puedeEditarOwner(owner, projIdParam) {\r\n        return String(owner || '').toLowerCase() === currentUserEmail || esLiderProyectoActual(projIdParam);\r\n    }\r\n\r\n    function actualizarPermisosProyecto() {\r\n        const fab = document.getElementById('leaderChatFab');\r\n        if (fab) fab.style.display = esLiderProyectoActual() ? 'inline-flex' : 'none';\r\n        actualizarHeaderChatProyecto();\r\n    }\r\n\r\n    window.__optimiaOnLoad_index = () => {\r\n        mEntry        = new bootstrap.Modal(document.getElementById('entryModal'), { backdrop: true, keyboard: true, focus: false });\r\n        mNota         = new bootstrap.Modal(document.getElementById('notaModal'));\r\n        mKanbanDetail = new bootstrap.Modal(document.getElementById('kanbanDetailModal'));\r\n        mAtraso       = new bootstrap.Modal(document.getElementById('alertaAtrasoModal'));\r\n        mGeneral      = new bootstrap.Modal(document.getElementById('generalInfoModal'), { backdrop: true, keyboard: true, focus: false });\r\n\r\n        document.getElementById('notaModal').addEventListener('shown.bs.modal', () => {\r\n            if (!ckNota) {\r\n                ClassicEditor.create(document.getElementById('notaEditor'), CK_CONFIG).then(editor => {\r\n                    ckNota = editor;\r\n                    if (window._pendingNotaData !== undefined) {\r\n                        ckNota.setData(window._pendingNotaData);\r\n                        window._pendingNotaData = undefined;\r\n                    }\r\n                }).catch(err => console.error('CKEditor Nota error:', err));\r\n            } else if (window._pendingNotaData !== undefined) {\r\n                ckNota.setData(window._pendingNotaData);\r\n                window._pendingNotaData = undefined;\r\n            }\r\n        });\r\n\r\n        document.getElementById('generalInfoModal').addEventListener('shown.bs.modal', () => {\r\n            if (!ckGeneralAlerta) {\r\n                ClassicEditor.create(document.getElementById('gAlertaEditor'), CK_CONFIG).then(editor => {\r\n                    ckGeneralAlerta = editor;\r\n                    if (window._pendingGeneralAlertaData !== undefined) {\r\n                        ckGeneralAlerta.setData(window._pendingGeneralAlertaData);\r\n                        window._pendingGeneralAlertaData = undefined;\r\n                    }\r\n                }).catch(err => console.error('CKEditor General Alerta error:', err));\r\n            } else if (window._pendingGeneralAlertaData !== undefined) {\r\n                ckGeneralAlerta.setData(window._pendingGeneralAlertaData);\r\n                window._pendingGeneralAlertaData = undefined;\r\n            }\r\n\r\n            if (!ckGeneralBloq) {\r\n                ClassicEditor.create(document.getElementById('gBloqueanteEditor'), CK_CONFIG).then(editor => {\r\n                    ckGeneralBloq = editor;\r\n                    if (window._pendingGeneralBloqData !== undefined) {\r\n                        ckGeneralBloq.setData(window._pendingGeneralBloqData);\r\n                        window._pendingGeneralBloqData = undefined;\r\n                    }\r\n                }).catch(err => console.error('CKEditor General Bloqueante error:', err));\r\n            } else if (window._pendingGeneralBloqData !== undefined) {\r\n                ckGeneralBloq.setData(window._pendingGeneralBloqData);\r\n                window._pendingGeneralBloqData = undefined;\r\n            }\r\n\r\n            if (!ckGeneralNota) {\r\n                ClassicEditor.create(document.getElementById('gNotaEditor'), CK_CONFIG).then(editor => {\r\n                    ckGeneralNota = editor;\r\n                    if (window._pendingGeneralNotaData !== undefined) {\r\n                        ckGeneralNota.setData(window._pendingGeneralNotaData);\r\n                        window._pendingGeneralNotaData = undefined;\r\n                    }\r\n                }).catch(err => console.error('CKEditor General Nota error:', err));\r\n            } else if (window._pendingGeneralNotaData !== undefined) {\r\n                ckGeneralNota.setData(window._pendingGeneralNotaData);\r\n                window._pendingGeneralNotaData = undefined;\r\n            }\r\n        });\r\n\r\n        document.getElementById('generalInfoModal').addEventListener('focusin.bs.modal', e => {\r\n            if (e.target.closest('.ck-balloon-panel') || e.target.closest('.ck-body-wrapper')) {\r\n                e.stopImmediatePropagation();\r\n            }\r\n        }, true);\r\n\r\n        document.getElementById('entryModal').addEventListener('shown.bs.modal', () => {\r\n            if (!ckEditor) {\r\n                ClassicEditor.create(document.getElementById('fDesc'), CK_CONFIG).then(editor => {\r\n                    ckEditor = editor;\r\n                    editor.ui.focusTracker.on('change:isFocused', (evt, name, isFocused) => {\r\n                        const modalEl = document.getElementById('entryModal');\r\n                        if (!isFocused) {\r\n                            modalEl.removeAttribute('data-bs-focus');\r\n                        }\r\n                    });\r\n                    if (window._pendingCkData !== undefined) {\r\n                        ckEditor.setData(window._pendingCkData);\r\n                        window._pendingCkData = undefined;\r\n                    }\r\n                }).catch(err => console.error('CKEditor error:', err));\r\n            } else if (window._pendingCkData !== undefined) {\r\n                ckEditor.setData(window._pendingCkData);\r\n                window._pendingCkData = undefined;\r\n            }\r\n            if (window.$) {\r\n                $('#fCategoria').select2({ dropdownParent: $('#entryModal'), placeholder: 'Escribe para buscar...', allowClear: true, width: '100%' });\r\n            }\r\n            if (window._pendingFocusFieldId) {\r\n                const elFocus = document.getElementById(window._pendingFocusFieldId);\r\n                if (elFocus && !elFocus.disabled) elFocus.focus();\r\n                window._pendingFocusFieldId = undefined;\r\n            }\r\n        });\r\n\r\n        document.getElementById('entryModal').addEventListener('hidden.bs.modal', () => {\r\n            const dragAlert = document.getElementById('fKanbanDragAlert');\r\n            if (dragAlert) {\r\n                dragAlert.style.display = 'none';\r\n                dragAlert.innerHTML = '';\r\n            }\r\n        });\r\n\r\n        document.getElementById('entryModal').addEventListener('focusin.bs.modal', e => {\r\n            if (e.target.closest('.ck-balloon-panel') || e.target.closest('.ck-body-wrapper')) {\r\n                e.stopImmediatePropagation();\r\n            }\r\n        }, true);\r\n\r\n        showL(true);\r\n        google.script.run.withSuccessHandler(res => {\r\n            userList = res.userList || []; currentUserEmail = res.email.toLowerCase();\r\n            usuariosPorEmail = new Map((res.usuarios || []).map(u => [u.email.toLowerCase(), u]));\r\n            categorias = res.categorias || [];\r\n            proyectosData = res.projects || [];\r\n            asignacionesData = res.asignaciones || [];\r\n            const selP = document.getElementById('projSelect'),\r\n                  selFP = document.getElementById('fProj'),\r\n                  selKCat = document.getElementById('kCatFilter');\r\n\r\n            categorias.forEach(c => {\r\n                selKCat.add(new Option(c.nombre, c.nombre));\r\n            });\r\n\r\n            if (res.projects.length > 0) {\r\n                hasProjects = true;\r\n                res.projects.forEach(p => { selP.add(new Option(p.nombre, p.id)); selFP.add(new Option(p.nombre, p.id)); });\r\n                selP.value = res.projects[0].id;\r\n                actualizarColaboradoresSelect();\r\n                document.getElementById('btnNewTask').style.display = 'inline-flex';\r\n                document.getElementById('btnGeneralInfo').style.display = 'inline-flex';\r\n\r\n                actualizarPermisosProyecto();\r\n\r\n                loadData();\r\n            } else {\r\n                document.getElementById('mainUI').innerHTML = \"<div class='alert alert-warning m-3'>No tienes proyectos asignados.</div>\";\r\n                showL(false);\r\n            }\r\n        }).getAppData();\r\n    };\r\n\r\n    // ══════════════════════════════════════════════════\r\n    //  FUNCIONES DE MORGAN (CHAT EXCLUSIVO PARA LÍDERES CON SALIDA HTML SEGURA)\r\n    // ══════════════════════════════════════════════════\r\n    function obtenerNombreProyectoActual() {\r\n        const selP = document.getElementById('projSelect');\r\n        return (selP && selP.options[selP.selectedIndex]) ? selP.options[selP.selectedIndex].text : 'Proyecto actual';\r\n    }\r\n\r\n    function actualizarHeaderChatProyecto() {\r\n        const lbl = document.getElementById('leaderChatProjLabel');\r\n        if (lbl) lbl.textContent = '📁 ' + obtenerNombreProyectoActual();\r\n    }\r\n\r\n    function toggleLeaderChat() {\r\n        if (!esLiderProyectoActual()) return;\r\n        const widget = document.getElementById('leaderChatWidget');\r\n        const isVisible = widget.style.display === 'flex';\r\n        widget.style.display = isVisible ? 'none' : 'flex';\r\n        if (!isVisible) {\r\n            actualizarHeaderChatProyecto();\r\n            setTimeout(() => document.getElementById('leaderChatInput').focus(), 80);\r\n        }\r\n    }\r\n\r\n    function sanitizarHtmlMorgan(rawHtml) {\r\n        if (!rawHtml) return '';\r\n        let s = String(rawHtml)\r\n            .replace(/<script[\\s\\S]*?>[\\s\\S]*?<\\/script>/gi, '')\r\n            .replace(/<style[\\s\\S]*?>[\\s\\S]*?<\\/style>/gi, '')\r\n            .replace(/\\son\\w+\\s*=\\s*(\"[^\"]*\"|'[^']*'|[^\\s>]+)/gi, '');\r\n        if (!/<(ul|ol|li|p|strong|b|em|br|div|span)\\b/i.test(s)) {\r\n            s = s.replace(/\\n/g, '<br>');\r\n        }\r\n        return s;\r\n    }\r\n\r\n    function limpiarChatLider() {\r\n        const box = document.getElementById('leaderChatMessages');\r\n        box.innerHTML = '';\r\n        agregarBurbujaChat('bot', `Conversación con <strong>Morgan 🐾</strong> reiniciada para el proyecto <strong>${obtenerNombreProyectoActual()}</strong>. ¿Qué deseas buscar o consultar?`, true);\r\n    }\r\n\r\n    function agregarBurbujaChat(rol, contenido, esHtml = false) {\r\n        const box = document.getElementById('leaderChatMessages');\r\n        const div = document.createElement('div');\r\n        div.className = 'chat-msg-bubble ' + (rol === 'user' ? 'chat-msg-user' : 'chat-msg-bot');\r\n        if (rol === 'bot' && esHtml) {\r\n            div.innerHTML = sanitizarHtmlMorgan(contenido);\r\n        } else {\r\n            div.textContent = contenido;\r\n        }\r\n        box.appendChild(div);\r\n        box.scrollTop = box.scrollHeight;\r\n        return div;\r\n    }\r\n\r\n    function enviarPreguntaRapidaChat(pregunta) {\r\n        const input = document.getElementById('leaderChatInput');\r\n        input.value = pregunta;\r\n        enviarPreguntaChatLider();\r\n    }\r\n\r\n    function enviarPreguntaChatLider() {\r\n        if (!esLiderProyectoActual()) return;\r\n        const input = document.getElementById('leaderChatInput');\r\n        const btn   = document.getElementById('leaderChatSendBtn');\r\n        const pregunta = input.value.trim();\r\n        if (!pregunta) return;\r\n\r\n        const projId   = document.getElementById('projSelect').value;\r\n        const projName = obtenerNombreProyectoActual();\r\n\r\n        agregarBurbujaChat('user', pregunta, false);\r\n        input.value = '';\r\n        input.disabled = true;\r\n        btn.disabled = true;\r\n\r\n        const loadingBubble = agregarBurbujaChat('bot', '🐾 Morgan está corriendo...', false);\r\n\r\n        google.script.run\r\n            .withSuccessHandler(res => {\r\n                input.disabled = false;\r\n                btn.disabled = false;\r\n                input.focus();\r\n                if (res && res.success) {\r\n                    loadingBubble.innerHTML = sanitizarHtmlMorgan(res.answer);\r\n                } else {\r\n                    loadingBubble.textContent = (res && res.error) ? res.error : 'No fue posible obtener respuesta.';\r\n                }\r\n                const box = document.getElementById('leaderChatMessages');\r\n                box.scrollTop = box.scrollHeight;\r\n            })\r\n            .withFailureHandler(err => {\r\n                input.disabled = false;\r\n                btn.disabled = false;\r\n                loadingBubble.textContent = 'Error al consultar a Morgan: ' + err.message;\r\n            })\r\n            .consultarChatLiderBedrock({\r\n                projectId:   projId,\r\n                projectName: projName,\r\n                question:    pregunta\r\n            });\r\n    }\r\n\r\n    function actualizarColaboradoresSelect() {\r\n        const selU  = document.getElementById('userSelect');\r\n        const selFO = document.getElementById('fOwner');\r\n        const selGO = document.getElementById('gOwner');\r\n        const previo = selU.value;\r\n\r\n        selU.innerHTML  = '';\r\n        selFO.innerHTML = '';\r\n        selGO.innerHTML = '';\r\n\r\n        const colaboradoresAsignados = obtenerColaboradoresProyectoActual();\r\n\r\n        const listaModal = colaboradoresAsignados.length > 0 ? colaboradoresAsignados : [currentUserEmail];\r\n        listaModal.forEach(u => {\r\n            selFO.add(new Option(nombreDeEmail(u), u));\r\n            selGO.add(new Option(nombreDeEmail(u), u));\r\n        });\r\n\r\n        if (!esLiderProyectoActual()) {\r\n            selU.add(new Option(nombreDeEmail(currentUserEmail), currentUserEmail));\r\n            selU.value = currentUserEmail;\r\n            return;\r\n        }\r\n\r\n        selU.add(new Option('VISTA GLOBAL', 'TODOS'));\r\n\r\n        const opcionesSelector = Array.from(new Set([currentUserEmail, ...colaboradoresAsignados].filter(Boolean)))\r\n            .sort((a, b) => nombreDeEmail(a).localeCompare(nombreDeEmail(b), 'es'));\r\n        opcionesSelector.forEach(u => selU.add(new Option(nombreDeEmail(u), u)));\r\n\r\n        if (previo && Array.from(selU.options).some(o => o.value === previo)) {\r\n            selU.value = previo;\r\n        } else {\r\n            selU.value = currentUserEmail;\r\n        }\r\n    }\r\n\r\n    function changeTab(t) {\r\n        currentTab = t;\r\n        document.getElementById('btnGest').className   = t === 'gestion' ? 'nav-seg-btn active' : 'nav-seg-btn';\r\n        document.getElementById('btnRepo').className   = t === 'reporte' ? 'nav-seg-btn active' : 'nav-seg-btn';\r\n        document.getElementById('btnEstado').className = t === 'estado'  ? 'nav-seg-btn active' : 'nav-seg-btn';\r\n\r\n        const info = TAB_INFO_MAP[t] || TAB_INFO_MAP['gestion'];\r\n        document.getElementById('tabInfoIcon').innerHTML  = info.icon;\r\n        document.getElementById('tabInfoTitle').innerText = info.title;\r\n        document.getElementById('tabInfoDesc').innerText  = info.desc;\r\n\r\n        document.getElementById('filterSection').style.display          = (t === 'reporte' || t === 'estado') ? 'block' : 'none';\r\n        document.getElementById('reporteCorreoBtnWrap').style.display   = t === 'reporte' ? 'flex'  : 'none';\r\n        document.getElementById('reporteExtraSearchWrap').style.display = t === 'reporte' ? 'block' : 'none';\r\n        document.getElementById('reporteVisualFilters').style.display   = t === 'reporte' ? 'flex'  : 'none';\r\n        document.getElementById('kanbanExtraSearchWrap').style.display  = t === 'estado'  ? 'block' : 'none';\r\n        document.getElementById('kanbanLeaderFilters').style.display    = t === 'estado'  ? 'flex'  : 'none';\r\n\r\n        document.getElementById('btnNewTask').style.display     = (t === 'gestion' && hasProjects) ? 'inline-flex' : 'none';\r\n        document.getElementById('btnGeneralInfo').style.display = (t === 'gestion' && hasProjects) ? 'inline-flex' : 'none';\r\n\r\n        if (t === 'estado') renderKanban();\r\n        else renderUI();\r\n    }\r\n\r\n    function aplicarFiltro() {\r\n        if (currentTab === 'estado') renderKanban();\r\n        else renderUI();\r\n    }\r\n\r\n    function limpiarFiltrosKanban() {\r\n        document.getElementById('f1').value = '';\r\n        document.getElementById('f2').value = '';\r\n        document.getElementById('kSearch').value = '';\r\n        document.getElementById('kCatFilter').value = '';\r\n        document.getElementById('kAlertFilter').value = '';\r\n        renderKanban();\r\n    }\r\n\r\n    function limpiarFiltrosReporte() {\r\n        document.getElementById('f1').value = '';\r\n        document.getElementById('f2').value = '';\r\n        document.getElementById('rSearch').value = '';\r\n        document.getElementById('rTaskCondFilter').value = '';\r\n        document.getElementById('rAvEstFilter').value = '';\r\n        renderUI();\r\n    }\r\n\r\n    function loadData() {\r\n        showL(true);\r\n        const u = document.getElementById('userSelect').value, p = document.getElementById('projSelect').value;\r\n        const cb = data => {\r\n            rawData = data;\r\n            notasData = {};\r\n            rawData.filter(e => e.tipo === 'Tarea' && e.nota).forEach(t => { notasData[t.id] = t.nota; });\r\n            if (currentTab === 'estado') renderKanban();\r\n            else renderUI();\r\n            showL(false);\r\n        };\r\n        if (u === \"TODOS\") {\r\n            const colaboradoresProyecto = obtenerColaboradoresProyectoActual(p);\r\n            google.script.run.withSuccessHandler(cb).fetchAllEntries(colaboradoresProyecto, p);\r\n        } else {\r\n            google.script.run.withSuccessHandler(cb).fetchEntries(u, p);\r\n        }\r\n    }\r\n\r\n    function validateDate(av) {\r\n        const f1 = document.getElementById('f1').value, f2 = document.getElementById('f2').value;\r\n        if (!f1 || !f2) return true;\r\n        const d1 = new Date(f1 + \"T00:00:00\"), d2 = new Date(f2 + \"T00:00:00\");\r\n        if (av.estado === 'Completado') {\r\n            if (!av.fechaFin) return false;\r\n            const dFin = new Date(av.fechaFin + \"T00:00:00\");\r\n            return dFin >= d1 && dFin <= d2;\r\n        }\r\n        if (!av.fechaInicio) return false;\r\n        const dInicio = new Date(av.fechaInicio + \"T00:00:00\");\r\n        return dInicio <= d2;\r\n    }\r\n\r\n    function calcularVigenciaAvance(av) {\r\n        if (!av.fechaInicio) return { texto: '-', dias: null };\r\n        const finStr = av.fechaFin || new Date().toISOString().split('T')[0];\r\n        const d1 = new Date(av.fechaInicio + \"T00:00:00\");\r\n        const d2 = new Date(finStr + \"T00:00:00\");\r\n        const dias = Math.max(0, Math.round((d2 - d1) / 86400000)) + 1;\r\n        const finLabel = av.fechaFin ? av.fechaFin : 'En proceso (hoy)';\r\n        return { texto: `${av.fechaInicio} hasta ${finLabel}`, dias };\r\n    }\r\n\r\n    function renderAvanceDetalleHtml(av) {\r\n        const obsInfo = separarObservacionesYAtrasos(av.observaciones || '');\r\n        const vigencia = calcularVigenciaAvance(av);\r\n\r\n        const atrasosHtml = obsInfo.atrasos.length\r\n            ? `<div class=\"col-12 mt-3\">\r\n                    <div class=\"small fw-bold mb-2\" style=\"color:#ad6800;\">⏰ Avances con atraso registrados</div>\r\n                    ${obsInfo.atrasos.map(a => `\r\n                        <div class=\"hist-atraso-item\">\r\n                            <div class=\"hist-atraso-fecha\">${a.fecha}</div>\r\n                            <div>${a.texto}</div>\r\n                        </div>\r\n                    `).join('')}\r\n                </div>`\r\n            : '';\r\n        const alertaAvanceHtml = tieneContenidoHtml(av.alerta)\r\n            ? `<div class=\"col-12 mt-2\"><div class=\"p-2 rounded\" style=\"background:#fffbe6;border-left:3px solid #FAAD14;\"><strong style=\"color:#ad6800;\">⚠️ Detenido por Alerta:</strong> ${av.alerta}</div></div>`\r\n            : '';\r\n        const bloqAvanceHtml = tieneContenidoHtml(av.bloqueante)\r\n            ? `<div class=\"col-12 mt-2\"><div class=\"p-2 rounded\" style=\"background:#fff1f0;border-left:3px solid #FF4D4F;\"><strong style=\"color:#cf1322;\">🔴 Detenido por Bloqueante:</strong> ${av.bloqueante}</div></div>`\r\n            : '';\r\n        return `\r\n            <div class=\"avance-card-detail\">\r\n                <div class=\"d-flex justify-content-between align-items-center mb-2\">\r\n                    ${renderBadgeEstadoHtml(av.estado, av)}\r\n                    <span class=\"small text-muted\"><strong>Vigencia:</strong> ${vigencia.texto}${vigencia.dias !== null ? ` <strong>(${vigencia.dias} día${vigencia.dias === 1 ? '' : 's'})</strong>` : ''}</span>\r\n                </div>\r\n                <div class=\"mb-2 ck-content-render\"><strong>Descripción:</strong> ${av.desc}</div>\r\n                <div class=\"row text-muted small\">\r\n                    <div class=\"col-md-6\"><strong>¿Tiene Entregable?:</strong> ${av.sinEntregable ? 'No' : 'Sí'}</div>\r\n                    <div class=\"col-md-6\"><strong>Entregable:</strong> ${av.entregable ? `<a href=\"${av.entregable}\" target=\"_blank\" style=\"color:#1890FF;\">Enlace</a>` : (av.sinEntregable ? 'N/A' : '-')}</div>\r\n                    <div class=\"col-md-6 mt-1\"><strong>Evidencia:</strong> ${av.evidencia ? (av.evidencia.startsWith('http') ? `<a href=\"${av.evidencia}\" target=\"_blank\" style=\"color:#1890FF;\">Enlace</a>` : av.evidencia) : '-'}</div>\r\n                    <div class=\"col-md-6 mt-1\"><strong>Justificación/Obs:</strong> ${obsInfo.textoLibre || '-'}</div>\r\n                    ${alertaAvanceHtml}\r\n                    ${bloqAvanceHtml}\r\n                    ${atrasosHtml}\r\n                </div>\r\n            </div>\r\n        `;\r\n    }\r\n\r\n    // ══════════════════════════════════════════════════\r\n    //  TABLERO KANBAN AGRUPADO POR:\r\n    //  Recuadro Tarea -> Registro Subtarea -> Post-it (Solo Avance)\r\n    //  4 Columnas: No iniciado, En proceso, Detenido, Completado\r\n    // ══════════════════════════════════════════════════\r\n    function renderKanban() {\r\n        const cont = document.getElementById('mainUI');\r\n        const selUser = document.getElementById('userSelect').value;\r\n        const searchQ = (document.getElementById('kSearch') ? document.getElementById('kSearch').value : '').toLowerCase().trim();\r\n        const catFilter = document.getElementById('kCatFilter') ? document.getElementById('kCatFilter').value : '';\r\n        const alertFilter = document.getElementById('kAlertFilter') ? document.getElementById('kAlertFilter').value : '';\r\n\r\n        const colaboradoresAsignados = obtenerColaboradoresProyectoActual();\r\n\r\n        const mapById = {};\r\n        rawData.forEach(e => { mapById[e.id] = e; });\r\n\r\n        let avances = rawData.filter(e =>\r\n            e.tipo === 'Avance' &&\r\n            e.estado !== 'Eliminada' &&\r\n            (selUser === 'TODOS' ? colaboradoresAsignados.includes((e.owner || '').toLowerCase()) : e.owner === selUser) &&\r\n            validateDate(e)\r\n        );\r\n\r\n        let items = avances.map(av => {\r\n            const subtarea = mapById[av.parentId] || null;\r\n            const tarea = (subtarea && mapById[subtarea.parentId]) ? mapById[subtarea.parentId] : null;\r\n            const tareaIdKey = tarea ? tarea.id : 'SIN_TAREA';\r\n            const subtareaIdKey = subtarea ? subtarea.id : 'SIN_SUBTAREA';\r\n            const nombreTarea = tarea ? textoPlano(tarea.desc) : 'Sin tarea asociada';\r\n            const nombreSubtarea = subtarea ? textoPlano(subtarea.desc) : 'Sin subtarea asociada';\r\n            const infoAtraso = calcularInfoAtraso(av);\r\n            const tieneBloq = av.estado === 'Detenido' && tieneContenidoHtml(av.bloqueante);\r\n            const tieneAlerta = av.estado === 'Detenido' && tieneContenidoHtml(av.alerta);\r\n            return { av, subtarea, tarea, tareaIdKey, subtareaIdKey, nombreTarea, nombreSubtarea, infoAtraso, tieneBloq, tieneAlerta };\r\n        });\r\n\r\n        if (searchQ) {\r\n            items = items.filter(it =>\r\n                it.nombreTarea.toLowerCase().includes(searchQ) ||\r\n                it.nombreSubtarea.toLowerCase().includes(searchQ) ||\r\n                textoPlano(it.av.desc).toLowerCase().includes(searchQ) ||\r\n                (it.av.owner || '').toLowerCase().includes(searchQ)\r\n            );\r\n        }\r\n        if (catFilter) {\r\n            items = items.filter(it => (it.av.categoria || '') === catFilter);\r\n        }\r\n        if (alertFilter === 'atraso') {\r\n            items = items.filter(it => it.infoAtraso.enAtraso);\r\n        } else if (alertFilter === 'bloqueante') {\r\n            items = items.filter(it => it.tieneBloq);\r\n        } else if (alertFilter === 'alerta') {\r\n            items = items.filter(it => it.tieneAlerta);\r\n        } else if (alertFilter === 'sin_entregable') {\r\n            items = items.filter(it => it.av.sinEntregable);\r\n        }\r\n\r\n        const COLUMNAS = [\r\n            { key: 'No iniciado', label: '⚪ No iniciado', headerBg: '#8C8C8C', defaultCardClass: 'postit-noiniciado' },\r\n            { key: 'En proceso',  label: '🔵 En Proceso',  headerBg: '#1890FF', defaultCardClass: 'postit-proceso' },\r\n            { key: 'Detenido',    label: '🛑 Detenido',    headerBg: '#D97706', defaultCardClass: 'postit-detenido-alerta' },\r\n            { key: 'Completado',  label: '🟢 Completado',  headerBg: '#52C41A', defaultCardClass: 'postit-completado' }\r\n        ];\r\n\r\n        const totalActividades = items.length;\r\n        const totalAtrasadas   = items.filter(i => i.infoAtraso.enAtraso).length;\r\n        const totalBloqueadas  = items.filter(i => i.tieneBloq).length;\r\n        const totalAlertas     = items.filter(i => i.tieneAlerta).length;\r\n\r\n        let html = `\r\n        <div class=\"kanban-summary-bar d-flex flex-wrap justify-content-between align-items-center small\">\r\n            <div class=\"d-flex align-items-center gap-2\">\r\n                <span class=\"fw-bold text-dark\"><i class=\"bi bi-kanban me-1\"></i>Vista de Seguimiento:</span>\r\n                <span class=\"badge bg-dark rounded-pill px-2\">${selUser === 'TODOS' ? 'TODOS LOS COLABORADORES ASIGNADOS' : selUser}</span>\r\n                <span class=\"text-muted ms-1\">Actividades: <strong>${totalActividades}</strong></span>\r\n            </div>\r\n            <div class=\"d-flex gap-2 align-items-center flex-wrap\">\r\n                ${totalAtrasadas > 0 ? `<span class=\"badge rounded-pill\" style=\"background:#fffbe6;color:#ad6800;border:1px solid #FAAD14;\">⏰ ${totalAtrasadas} con atraso (+7d)</span>` : ''}\r\n                ${totalAlertas > 0 ? `<span class=\"badge rounded-pill\" style=\"background:#fffbe6;color:#ad6800;border:1px solid #FAAD14;\">🟡 ${totalAlertas} detenida(s) por Alerta</span>` : ''}\r\n                ${totalBloqueadas > 0 ? `<span class=\"badge rounded-pill\" style=\"background:#fff1f0;color:#cf1322;border:1px solid #FF4D4F;\">🔴 ${totalBloqueadas} detenida(s) por Bloqueante</span>` : ''}\r\n                <span class=\"text-muted fst-italic\"><i class=\"bi bi-arrows-move me-1\"></i>Arrastra actividades activas entre estados o haz clic sobre un post-it para ver su ficha</span>\r\n            </div>\r\n        </div>\r\n        <div class=\"kanban-board\">`;\r\n\r\n        COLUMNAS.forEach(col => {\r\n            const colItems = items\r\n                .filter(it => it.av.estado === col.key)\r\n                .sort((a, b) => {\r\n                    if (col.key === 'Detenido' && a.tieneBloq !== b.tieneBloq) {\r\n                        return a.tieneBloq ? -1 : 1;\r\n                    }\r\n                    if (col.key !== 'Completado' && a.infoAtraso.enAtraso !== b.infoAtraso.enAtraso) {\r\n                        return a.infoAtraso.enAtraso ? -1 : 1;\r\n                    }\r\n                    const da = a.av.fechaInicio ? new Date(a.av.fechaInicio + 'T00:00:00').getTime() : 0;\r\n                    const db = b.av.fechaInicio ? new Date(b.av.fechaInicio + 'T00:00:00').getTime() : 0;\r\n                    return db - da;\r\n                });\r\n\r\n            html += `\r\n            <div class=\"kanban-col\"\r\n                 data-estado=\"${col.key}\"\r\n                 ondragover=\"onKanbanDragOver(event, this)\"\r\n                 ondragleave=\"onKanbanDragLeave(event, this)\"\r\n                 ondrop=\"onKanbanDrop(event, '${col.key}', this)\">\r\n                <div class=\"kanban-col-header\" style=\"background:${col.headerBg};\">\r\n                    <span>${col.label}</span>\r\n                    <span class=\"badge bg-light text-dark rounded-pill\">${colItems.length}</span>\r\n                </div>\r\n                <div class=\"kanban-col-body\">`;\r\n\r\n            if (colItems.length === 0) {\r\n                html += `<div class=\"text-center text-muted small py-5\" style=\"opacity:0.65;\">\r\n                    <i class=\"bi bi-inbox d-block mb-1\" style=\"font-size:1.2rem;\"></i>\r\n                    Arrastra una actividad aquí\r\n                </div>`;\r\n            } else {\r\n                const tareasMap = new Map();\r\n                colItems.forEach(it => {\r\n                    if (!tareasMap.has(it.tareaIdKey)) {\r\n                        tareasMap.set(it.tareaIdKey, {\r\n                            nombreTarea: it.nombreTarea,\r\n                            subtareasMap: new Map()\r\n                        });\r\n                    }\r\n                    const tGroup = tareasMap.get(it.tareaIdKey);\r\n                    if (!tGroup.subtareasMap.has(it.subtareaIdKey)) {\r\n                        tGroup.subtareasMap.set(it.subtareaIdKey, {\r\n                            nombreSubtarea: it.nombreSubtarea,\r\n                            avancesList: []\r\n                        });\r\n                    }\r\n                    tGroup.subtareasMap.get(it.subtareaIdKey).avancesList.push(it);\r\n                });\r\n\r\n                tareasMap.forEach(tGroup => {\r\n                    html += `\r\n                    <div class=\"kanban-task-group\">\r\n                        <div class=\"kanban-task-header\" title=\"${limpiarTextoAttr(tGroup.nombreTarea, 160)}\">\r\n                            <i class=\"bi bi-layers-fill\"></i>\r\n                            <span>${tGroup.nombreTarea}</span>\r\n                        </div>`;\r\n\r\n                    tGroup.subtareasMap.forEach(stGroup => {\r\n                        html += `\r\n                        <div class=\"kanban-subtask-group\">\r\n                            <div class=\"kanban-subtask-header\" title=\"${limpiarTextoAttr(stGroup.nombreSubtarea, 160)}\">\r\n                                <i class=\"bi bi-folder2-open\"></i>\r\n                                <span>${stGroup.nombreSubtarea}</span>\r\n                            </div>\r\n                            <div class=\"kanban-subtask-postits\">`;\r\n\r\n                        stGroup.avancesList.forEach(it => {\r\n                            const indicadores = [];\r\n                            const tienePermisoEdicion = puedeEditarOwner(it.av.owner, it.av.projectId);\r\n\r\n                            if (it.infoAtraso.enAtraso) {\r\n                                indicadores.push(`<span class=\"badge rounded-pill\" style=\"background:#fffbe6;color:#ad6800;border:1px solid #FAAD14;font-size:0.6rem;\" title=\"En atraso (${it.infoAtraso.diasAtraso} días)\">⏰ ${it.infoAtraso.diasAtraso}d</span>`);\r\n                            }\r\n                            if (it.tieneBloq) {\r\n                                indicadores.push(`<span class=\"badge rounded-pill\" style=\"background:#fff1f0;color:#cf1322;border:1px solid #FF4D4F;font-size:0.6rem;\" title=\"Detenido por Bloqueante\">🔴 Bloqueante</span>`);\r\n                            } else if (it.tieneAlerta) {\r\n                                indicadores.push(`<span class=\"badge rounded-pill\" style=\"background:#fffbe6;color:#ad6800;border:1px solid #FAAD14;font-size:0.6rem;\" title=\"Detenido por Alerta\">⚠️ Alerta</span>`);\r\n                            }\r\n                            if (it.av.interno) {\r\n                                indicadores.push(`<span title=\"Actividad interna\">🔒</span>`);\r\n                            }\r\n\r\n                            const userShort = nombreDeEmail(it.av.owner);\r\n                            const iniciales = obtenerInicialesEmail(it.av.owner);\r\n\r\n                            const puedeMover = tienePermisoEdicion && it.av.estado !== 'Completado';\r\n\r\n                            const postitColorClass = col.key === 'Detenido'\r\n                                ? (it.tieneBloq ? 'postit-detenido-bloq' : 'postit-detenido-alerta')\r\n                                : col.defaultCardClass;\r\n\r\n                            html += `\r\n                            <div class=\"postit-card ${postitColorClass} ${puedeMover ? '' : 'no-drag'}\"\r\n                                 draggable=\"${puedeMover ? 'true' : 'false'}\"\r\n                                 ondragstart=\"onPostitDragStart(event, '${it.av.id}', this)\"\r\n                                 ondragend=\"onPostitDragEnd(event, this)\"\r\n                                 onclick=\"onPostitClick(event, '${it.av.id}')\">\r\n                                <div class=\"postit-avance ck-content-render\">${it.av.desc}</div>\r\n                                <div class=\"postit-indicators\">\r\n                                    <span class=\"postit-user-chip\">\r\n                                        <span class=\"postit-user-initials\">${iniciales}</span>\r\n                                        ${userShort}\r\n                                    </span>\r\n                                    <span class=\"d-flex align-items-center gap-1\">${indicadores.join(' ')}</span>\r\n                                </div>\r\n                            </div>`;\r\n                        });\r\n\r\n                        html += `</div></div>`;\r\n                    });\r\n\r\n                    html += `</div>`;\r\n                });\r\n            }\r\n\r\n            html += `</div></div>`;\r\n        });\r\n\r\n        html += `</div>`;\r\n        cont.innerHTML = html;\r\n    }\r\n\r\n    // ══════════════════════════════════════════════════\r\n    //  EVENTOS DRAG & DROP Y VALIDACIÓN DE CAMBIO DE ESTADO\r\n    // ══════════════════════════════════════════════════\r\n    function onPostitClick(e, avanceId) {\r\n        if (isDraggingPostit) return;\r\n        if (e.target.closest('a') || e.target.closest('button')) return;\r\n        abrirDetalleKanban(avanceId);\r\n    }\r\n\r\n    function onPostitDragStart(e, avanceId, cardEl) {\r\n        const av = rawData.find(x => x.id === avanceId);\r\n        if (!av || av.estado === 'Completado' || !puedeEditarOwner(av.owner, av.projectId)) {\r\n            e.preventDefault();\r\n            return;\r\n        }\r\n        isDraggingPostit = true;\r\n        draggedAvanceId = avanceId;\r\n        e.dataTransfer.effectAllowed = 'move';\r\n        e.dataTransfer.setData('text/plain', avanceId);\r\n        setTimeout(() => cardEl.classList.add('dragging'), 0);\r\n    }\r\n\r\n    function onPostitDragEnd(e, cardEl) {\r\n        cardEl.classList.remove('dragging');\r\n        document.querySelectorAll('.kanban-col.drag-over').forEach(c => c.classList.remove('drag-over'));\r\n        setTimeout(() => { isDraggingPostit = false; draggedAvanceId = null; }, 80);\r\n    }\r\n\r\n    function onKanbanDragOver(e, colEl) {\r\n        e.preventDefault();\r\n        e.dataTransfer.dropEffect = 'move';\r\n        if (!colEl.classList.contains('drag-over')) {\r\n            colEl.classList.add('drag-over');\r\n        }\r\n    }\r\n\r\n    function onKanbanDragLeave(e, colEl) {\r\n        if (!colEl.contains(e.relatedTarget)) {\r\n            colEl.classList.remove('drag-over');\r\n        }\r\n    }\r\n\r\n    function onKanbanDrop(e, nuevoEstado, colEl) {\r\n        e.preventDefault();\r\n        colEl.classList.remove('drag-over');\r\n\r\n        const avanceId = draggedAvanceId || e.dataTransfer.getData('text/plain');\r\n        if (!avanceId) return;\r\n\r\n        const av = rawData.find(x => x.id === avanceId);\r\n        if (!av || av.estado === nuevoEstado) return;\r\n\r\n        if (av.estado === 'Completado') {\r\n            return;\r\n        }\r\n\r\n        if (!puedeEditarOwner(av.owner, av.projectId)) {\r\n            alert('⚠️ Solo el responsable de la actividad o el líder del proyecto pueden cambiar su estado.');\r\n            return;\r\n        }\r\n\r\n        procesarCambioEstadoKanban(av, nuevoEstado);\r\n    }\r\n\r\n    function procesarCambioEstadoKanban(av, nuevoEstado) {\r\n        const faltantes = [];\r\n        let focusId = '';\r\n\r\n        const catActual        = String(av.categoria || '').trim();\r\n        const evActual         = String(av.evidencia || '').trim();\r\n        const entActual        = String(av.entregable || '').trim();\r\n        const obsInfo          = separarObservacionesYAtrasos(av.observaciones || '');\r\n        const obsLibreActual   = String(obsInfo.textoLibre || '').replace(/<br\\s*\\/?>/gi, ' ').trim();\r\n        const fechaFinActual   = String(av.fechaFin || '').trim();\r\n\r\n        const alertaActualizada     = (nuevoEstado === 'Detenido') ? (av.alerta || '') : '';\r\n        const bloqueanteActualizado = (nuevoEstado === 'Detenido') ? (av.bloqueante || '') : '';\r\n\r\n        if (!catActual) {\r\n            faltantes.push('Categoría');\r\n            if (!focusId) focusId = 'fCategoria';\r\n        }\r\n\r\n        if (nuevoEstado === 'Detenido') {\r\n            faltantes.push('Tipo de detención (Alerta o Bloqueante) y su justificación');\r\n            focusId = 'fTipoDetenido';\r\n        } else if (nuevoEstado === 'Completado') {\r\n            if (!fechaFinActual) {\r\n                faltantes.push('Fecha de Fin');\r\n                if (!focusId) focusId = 'fFi';\r\n            }\r\n            if (av.sinEntregable) {\r\n                if (!obsLibreActual && !String(av.observaciones || '').trim()) {\r\n                    faltantes.push('Observaciones (justificación de Sin Entregable)');\r\n                    if (!focusId) focusId = 'fObservaciones';\r\n                }\r\n            } else {\r\n                if (!evActual) {\r\n                    faltantes.push('Evidencia');\r\n                    if (!focusId) focusId = 'fEvidencia';\r\n                }\r\n                if (!entActual) {\r\n                    faltantes.push('Entregable');\r\n                    if (!focusId) focusId = 'fEntregable';\r\n                }\r\n            }\r\n        }\r\n\r\n        if (faltantes.length > 0) {\r\n            const hoySugerido = new Date().toISOString().split('T')[0];\r\n            const fechaFinModal = (nuevoEstado === 'Completado') ? (fechaFinActual || hoySugerido) : '';\r\n\r\n            const dragAlert = document.getElementById('fKanbanDragAlert');\r\n            if (dragAlert) {\r\n                dragAlert.style.display = 'block';\r\n                dragAlert.innerHTML = `📌 Moviste la actividad a <strong>${nuevoEstado}</strong>. Por favor completa: <strong>${faltantes.join(', ')}</strong>.`;\r\n            }\r\n            window._pendingFocusFieldId = focusId;\r\n\r\n            openModal(\r\n                av.tipo,\r\n                av.parentId,\r\n                av.id,\r\n                av.desc,\r\n                av.fechaInicio,\r\n                fechaFinModal,\r\n                nuevoEstado,\r\n                av.owner,\r\n                av.projectId,\r\n                alertaActualizada,\r\n                bloqueanteActualizado,\r\n                av.categoria || '',\r\n                av.jira || '',\r\n                av.msd || '',\r\n                av.espTecnica || '',\r\n                av.espFuncional || '',\r\n                av.evidencia || '',\r\n                av.sinEntregable || false,\r\n                av.observaciones || '',\r\n                av.entregable || '',\r\n                av.interno || false,\r\n                av.descripcionTarea || ''\r\n            );\r\n            return;\r\n        }\r\n\r\n        const fechaFinGuardar = (nuevoEstado === 'Completado') ? fechaFinActual : '';\r\n\r\n        showL(true);\r\n        const payload = {\r\n            userOwner:        av.owner,\r\n            projectId:        av.projectId,\r\n            id:               av.id,\r\n            tipo:             av.tipo,\r\n            parentId:         av.parentId,\r\n            desc:             av.desc,\r\n            fechaInicio:      av.fechaInicio,\r\n            fechaFin:         fechaFinGuardar,\r\n            estado:           nuevoEstado,\r\n            alerta:           alertaActualizada,\r\n            bloqueante:       bloqueanteActualizado,\r\n            categoria:        av.categoria    || '',\r\n            nota:             av.nota         || '',\r\n            jira:             av.jira         || '',\r\n            msd:              av.msd          || '',\r\n            espTecnica:       av.espTecnica   || '',\r\n            espFuncional:     av.espFuncional || '',\r\n            evidencia:        av.evidencia    || '',\r\n            entregable:       av.entregable   || '',\r\n            sinEntregable:    av.sinEntregable || false,\r\n            interno:          av.interno      || false,\r\n            observaciones:    av.observaciones || '',\r\n            descripcionTarea: av.descripcionTarea || ''\r\n        };\r\n\r\n        google.script.run\r\n            .withSuccessHandler(() => loadData())\r\n            .withFailureHandler(err => { showL(false); alert('⚠️ ' + err.message); renderKanban(); })\r\n            .saveOrUpdateEntry(payload);\r\n    }\r\n\r\n    function abrirDetalleKanban(avanceId) {\r\n        const av = rawData.find(e => e.id === avanceId);\r\n        if (!av) return;\r\n\r\n        const subtarea = rawData.find(e => e.id === av.parentId) || null;\r\n        const tarea    = subtarea ? (rawData.find(e => e.id === subtarea.parentId) || null) : null;\r\n\r\n        const vigencia   = calcularVigenciaAvance(av);\r\n        const infoAtraso = calcularInfoAtraso(av);\r\n        const obsInfo    = separarObservacionesYAtrasos(av.observaciones || '');\r\n        const infoColAv  = obtenerInfoColorEstado(av.estado, av);\r\n        const puedeEditar = puedeEditarOwner(av.owner, av.projectId);\r\n\r\n        document.getElementById('kdHeaderOwner').innerText = `Responsable: ${nombreDeEmail(av.owner)}  |  Categoría: ${av.categoria || 'Sin categoría'}`;\r\n\r\n        const atrasosHtml = obsInfo.atrasos.length\r\n            ? `<div class=\"mt-3 pt-2 border-top\">\r\n                    <div class=\"modal-detail-title\" style=\"color:#ad6800;\">⏰ Historial de Justificaciones de Atraso (${obsInfo.atrasos.length})</div>\r\n                    ${obsInfo.atrasos.map(a => `\r\n                        <div class=\"hist-atraso-item\">\r\n                            <div class=\"hist-atraso-fecha\">📅 ${a.fecha}</div>\r\n                            <div>${a.texto}</div>\r\n                        </div>\r\n                    `).join('')}\r\n               </div>`\r\n            : '';\r\n\r\n        const alertaBloqAvanceHtml = (av.estado === 'Detenido' && (tieneContenidoHtml(av.alerta) || tieneContenidoHtml(av.bloqueante)))\r\n            ? `<div class=\"row g-2 mt-2 pt-2 border-top\">\r\n                ${tieneContenidoHtml(av.alerta) ? `\r\n                <div class=\"col-12\">\r\n                    <div class=\"nota-block mb-0\" style=\"background:#fffbe6;border-color:#ffe58f;border-left-color:#FAAD14;\">\r\n                        <div class=\"small fw-bold mb-1\" style=\"color:#ad6800;\">⚠️ Detenido por Alerta</div>\r\n                        <div class=\"small ck-content-render\" style=\"white-space:pre-wrap;\">${av.alerta}</div>\r\n                    </div>\r\n                </div>` : ''}\r\n                ${tieneContenidoHtml(av.bloqueante) ? `\r\n                <div class=\"col-12\">\r\n                    <div class=\"nota-block mb-0\" style=\"background:#fff1f0;border-color:#ffa39e;border-left-color:#FF4D4F;\">\r\n                        <div class=\"small fw-bold mb-1\" style=\"color:#cf1322;\">🔴 Detenido por Bloqueante</div>\r\n                        <div class=\"small ck-content-render\" style=\"white-space:pre-wrap;\">${av.bloqueante}</div>\r\n                    </div>\r\n                </div>` : ''}\r\n               </div>`\r\n            : '';\r\n\r\n        const notaTareaHtml = (tarea && tieneContenidoHtml(tarea.nota))\r\n            ? `<div class=\"nota-block ck-content-render mt-2 mb-0\">\r\n                    <div class=\"small fw-bold mb-1\" style=\"color:#0050b3;\">📝 Notas de la Tarea Principal</div>\r\n                    ${tarea.nota}\r\n               </div>`\r\n            : '';\r\n\r\n        const descTareaModalHtml = (tarea && tarea.descripcionTarea && tarea.descripcionTarea.trim())\r\n            ? `<div class=\"task-context-desc mt-1\">${tarea.descripcionTarea}</div>`\r\n            : '';\r\n\r\n        const bodyHtml = `\r\n            <!-- Jerarquía Tarea -> Subtarea -->\r\n            <div class=\"p-3 mb-3 rounded-3\" style=\"background:#f8f9fa;border:1px solid #dee2e6;border-left:5px solid #1890FF;\">\r\n                <div class=\"d-flex justify-content-between align-items-start flex-wrap gap-2 mb-2\">\r\n                    <div>\r\n                        <div class=\"modal-detail-title mb-0\">🗂️ Tarea Principal</div>\r\n                        <div class=\"fw-bold text-dark ck-content-render\">${tarea ? tarea.desc : 'Sin tarea asociada'}</div>\r\n                        ${descTareaModalHtml}\r\n                    </div>\r\n                    ${tarea ? renderBadgeEstadoHtml(tarea.estado, tarea) : ''}\r\n                </div>\r\n                <div class=\"d-flex justify-content-between align-items-start flex-wrap gap-2 pt-2 border-top\">\r\n                    <div>\r\n                        <div class=\"modal-detail-title mb-0\">📁 Subtarea</div>\r\n                        <div class=\"fw-semibold ck-content-render\" style=\"color:#1890FF;\">${subtarea ? subtarea.desc : 'Sin subtarea asociada'}</div>\r\n                    </div>\r\n                    ${subtarea ? renderBadgeEstadoHtml(subtarea.estado, subtarea) : ''}\r\n                </div>\r\n                ${notaTareaHtml}\r\n            </div>\r\n\r\n            <!-- Detalle de la Actividad (Avance) -->\r\n            <div class=\"p-3 mb-3 rounded-3\" style=\"background:#ffffff;border:1px solid #dee2e6;border-left:5px solid ${infoColAv.hex};\">\r\n                <div class=\"d-flex justify-content-between align-items-center flex-wrap gap-2 mb-2\">\r\n                    <div class=\"modal-detail-title mb-0\">📌 Avance / Actividad</div>\r\n                    <div class=\"d-flex gap-2 align-items-center\">\r\n                        ${av.interno ? `<span class=\"badge bg-dark\">🔒 Interno</span>` : ''}\r\n                        ${infoAtraso.enAtraso ? `<span class=\"badge\" style=\"background:#fffbe6;color:#ad6800;border:1px solid #FAAD14;\">⏰ ${infoAtraso.diasAtraso} días sin completar</span>` : ''}\r\n                        ${renderBadgeEstadoHtml(av.estado, av)}\r\n                    </div>\r\n                </div>\r\n                <div class=\"ck-content-render mb-3\" style=\"font-size:0.95rem;\">${av.desc}</div>\r\n\r\n                <div class=\"row g-3 pt-2 border-top\">\r\n                    <div class=\"col-sm-4\">\r\n                        <div class=\"modal-detail-title\">📅 Fecha Inicio</div>\r\n                        <div class=\"modal-detail-value fw-bold\">${av.fechaInicio || '-'}</div>\r\n                    </div>\r\n                    <div class=\"col-sm-4\">\r\n                        <div class=\"modal-detail-title\">🏁 Fecha Fin</div>\r\n                        <div class=\"modal-detail-value fw-bold\">${av.fechaFin || 'En curso'}</div>\r\n                    </div>\r\n                    <div class=\"col-sm-4\">\r\n                        <div class=\"modal-detail-title\">⏱️ Vigencia / Duración</div>\r\n                        <div class=\"modal-detail-value fw-bold\">${vigencia.dias !== null ? `${vigencia.dias} día(s)` : '-'}</div>\r\n                    </div>\r\n\r\n                    <div class=\"col-md-6\">\r\n                        <div class=\"modal-detail-title\">🔗 Evidencia</div>\r\n                        <div class=\"modal-detail-value\">${formatearEnlaceOTexto(av.evidencia)}</div>\r\n                    </div>\r\n                    <div class=\"col-md-6\">\r\n                        <div class=\"modal-detail-title\">📦 Entregable ${av.sinEntregable ? '<span class=\"badge ms-1\" style=\"background:#FAAD14;color:#fff;\">Marcado Sin Entregable</span>' : ''}</div>\r\n                        <div class=\"modal-detail-value\">${av.sinEntregable ? 'No aplica (Sin entregable)' : formatearEnlaceOTexto(av.entregable)}</div>\r\n                    </div>\r\n\r\n                    <div class=\"col-12\">\r\n                        <div class=\"modal-detail-title\">📝 Observaciones / Justificación</div>\r\n                        <div class=\"modal-detail-value\">${obsInfo.textoLibre || '-'}</div>\r\n                    </div>\r\n                </div>\r\n                ${alertaBloqAvanceHtml}\r\n                ${atrasosHtml}\r\n            </div>\r\n\r\n            <!-- Información Técnica y de Gestión de la Subtarea (Jira, MSD, Especificaciones) -->\r\n            ${subtarea && (subtarea.jira || subtarea.msd || subtarea.espTecnica || subtarea.espFuncional) ? `\r\n            <div class=\"p-3 rounded-3\" style=\"background:#f8f9fa;border:1px solid #dee2e6;\">\r\n                <div class=\"modal-detail-title mb-2\">🛠️ Ficha Técnica de la Subtarea</div>\r\n                <div class=\"row g-2\">\r\n                    <div class=\"col-md-6\">\r\n                        <div class=\"modal-detail-title\">Jira</div>\r\n                        <div class=\"modal-detail-value fw-bold\" style=\"color:#1890FF;\">${formatearEnlaceOTexto(subtarea.jira)}</div>\r\n                    </div>\r\n                    <div class=\"col-md-6\">\r\n                        <div class=\"modal-detail-title\">MSD</div>\r\n                        <div class=\"modal-detail-value fw-bold\" style=\"color:#52C41A;\">${formatearEnlaceOTexto(subtarea.msd)}</div>\r\n                    </div>\r\n                    ${subtarea.espTecnica ? `\r\n                    <div class=\"col-12 mt-2\">\r\n                        <div class=\"modal-detail-title\">Especificación Técnica</div>\r\n                        <div class=\"modal-detail-value text-muted\" style=\"white-space:pre-wrap;\">${subtarea.espTecnica}</div>\r\n                    </div>` : ''}\r\n                    ${subtarea.espFuncional ? `\r\n                    <div class=\"col-12 mt-2\">\r\n                        <div class=\"modal-detail-title\">Especificación Funcional</div>\r\n                        <div class=\"modal-detail-value text-muted\" style=\"white-space:pre-wrap;\">${subtarea.espFuncional}</div>\r\n                    </div>` : ''}\r\n                </div>\r\n            </div>` : ''}\r\n        `;\r\n\r\n        document.getElementById('kanbanDetailBody').innerHTML = bodyHtml;\r\n\r\n        const descLimpia = limpiarTextoAttr(av.desc, 40);\r\n        let footerHtml = `<button type=\"button\" class=\"btn btn-sm btn-soft fw-bold\" style=\"border-radius:7px;\" data-bs-dismiss=\"modal\">Cerrar</button><div class=\"d-flex gap-2\">`;\r\n        if (infoAtraso.enAtraso && infoAtraso.puedeJustificar) {\r\n            footerHtml += `<button type=\"button\" class=\"btn btn-sm btn-soft fw-bold\" style=\"border-radius:7px;background:#fffbe6;color:#ad6800;border-color:#FAAD14;\" onclick=\"mKanbanDetail.hide(); abrirAtraso('${av.id}','${av.owner}','${descLimpia}');\">⏰ Justificar Atraso</button>`;\r\n        }\r\n        if (puedeEditar) {\r\n            footerHtml += `<button type=\"button\" class=\"btn btn-sm btn-soft-primary fw-bold\" style=\"border-radius:7px;\" onclick=\"mKanbanDetail.hide(); edit('${av.id}');\">✏️ Editar Actividad</button>`;\r\n        }\r\n        footerHtml += `</div>`;\r\n        document.getElementById('kanbanDetailFooter').innerHTML = footerHtml;\r\n\r\n        mKanbanDetail.show();\r\n    }\r\n\r\n    // ══════════════════════════════════════════════════\r\n    //  ALERTAS, BLOQUEANTES Y NOTAS GENERALES (TODOS CON CKEDITOR)\r\n    // ══════════════════════════════════════════════════\r\n    function abrirModalGeneral(targetOwner) {\r\n        const selGO = document.getElementById('gOwner');\r\n        const selUser = document.getElementById('userSelect').value;\r\n        const ownerInicial = targetOwner || (esLiderProyectoActual()\r\n            ? (selUser === 'TODOS' ? currentUserEmail : selUser)\r\n            : currentUserEmail);\r\n\r\n        if (!Array.from(selGO.options).some(o => o.value === ownerInicial)) {\r\n            selGO.add(new Option(nombreDeEmail(ownerInicial), ownerInicial));\r\n        }\r\n        selGO.value = ownerInicial;\r\n        selGO.disabled = !esLiderProyectoActual();\r\n\r\n        cargarDatosModalGeneralPorUsuario();\r\n        mGeneral.show();\r\n    }\r\n\r\n    function cargarDatosModalGeneralPorUsuario() {\r\n        const owner = document.getElementById('gOwner').value;\r\n        const projId = document.getElementById('projSelect').value;\r\n        const genEntry = rawData.find(e => e.tipo === 'General' && e.owner === owner && String(e.projectId) === String(projId));\r\n\r\n        const alertaHtml = genEntry ? (genEntry.alerta || '') : '';\r\n        const bloqHtml   = genEntry ? (genEntry.bloqueante || '') : '';\r\n        const notaHtml   = genEntry ? (genEntry.nota || '') : '';\r\n\r\n        if (ckGeneralAlerta) ckGeneralAlerta.setData(alertaHtml);\r\n        else window._pendingGeneralAlertaData = alertaHtml;\r\n\r\n        if (ckGeneralBloq) ckGeneralBloq.setData(bloqHtml);\r\n        else window._pendingGeneralBloqData = bloqHtml;\r\n\r\n        if (ckGeneralNota) ckGeneralNota.setData(notaHtml);\r\n        else window._pendingGeneralNotaData = notaHtml;\r\n    }\r\n\r\n    function guardarInfoGeneral() {\r\n        const owner      = document.getElementById('gOwner').value;\r\n        const projectId  = document.getElementById('projSelect').value;\r\n        const alertaRaw  = ckGeneralAlerta ? ckGeneralAlerta.getData().trim() : '';\r\n        const bloqRaw    = ckGeneralBloq   ? ckGeneralBloq.getData().trim()   : '';\r\n        const notaRaw    = ckGeneralNota   ? ckGeneralNota.getData().trim()   : '';\r\n\r\n        const alerta     = tieneContenidoHtml(alertaRaw) ? alertaRaw : '';\r\n        const bloqueante = tieneContenidoHtml(bloqRaw)   ? bloqRaw   : '';\r\n        const nota       = tieneContenidoHtml(notaRaw)   ? notaRaw   : '';\r\n\r\n        showL(true);\r\n        google.script.run\r\n            .withSuccessHandler(() => { mGeneral.hide(); loadData(); })\r\n            .withFailureHandler(err => { showL(false); alert('Error: ' + err.message); })\r\n            .saveGeneralProjectInfo({ owner, projectId, alerta, bloqueante, nota });\r\n    }\r\n\r\n    function renderUI() {\r\n        const cont = document.getElementById('mainUI'); cont.innerHTML = \"\";\r\n        const selUser = document.getElementById('userSelect').value;\r\n        const p = document.getElementById('projSelect').value;\r\n        const targets = (selUser === \"TODOS\") ? obtenerColaboradoresProyectoActual(p) : [selUser];\r\n\r\n        const rSearch   = (currentTab === 'reporte' && document.getElementById('rSearch')) ? document.getElementById('rSearch').value.toLowerCase().trim() : '';\r\n        const rTaskCond = (currentTab === 'reporte' && document.getElementById('rTaskCondFilter')) ? document.getElementById('rTaskCondFilter').value : '';\r\n        const rAvEst    = (currentTab === 'reporte' && document.getElementById('rAvEstFilter')) ? document.getElementById('rAvEstFilter').value : '';\r\n\r\n        const omitirFiltroFechaPorBloqAlerta = (currentTab === 'reporte' && rTaskCond === 'con_bloqueantes_alertas');\r\n\r\n        targets.forEach(user => {\r\n            const uData = rawData.filter(d => (d.owner || '').toLowerCase() === user.toLowerCase());\r\n            if (uData.length > 0) {\r\n                const userBlock = document.createElement('div');\r\n                let hasVisibleContentForUser = false;\r\n\r\n                // ── Bloque de Alertas, Bloqueantes y Notas Generales del usuario ──\r\n                const genEntry = uData.find(e => e.tipo === 'General');\r\n                const tieneGenAlerta = genEntry && tieneContenidoHtml(genEntry.alerta);\r\n                const tieneGenBloq   = genEntry && tieneContenidoHtml(genEntry.bloqueante);\r\n                const tieneGenNota   = genEntry && tieneContenidoHtml(genEntry.nota);\r\n\r\n                const ocultarGenPorFiltroReporte = currentTab === 'reporte' && (rTaskCond || rAvEst || rSearch);\r\n\r\n                if (!ocultarGenPorFiltroReporte && (tieneGenAlerta || tieneGenBloq || tieneGenNota)) {\r\n                    hasVisibleContentForUser = true;\r\n                    const genDiv = document.createElement('div');\r\n                    genDiv.className = 'general-info-card';\r\n                    let genHtml = `<div class=\"d-flex justify-content-between align-items-center mb-2\">\r\n                        <span class=\"small fw-bold text-uppercase\" style=\"color:var(--optimia-black);letter-spacing:0.5px;\">📌 Información General del Proyecto</span>`;\r\n                    if (currentTab === 'gestion' && puedeEditarOwner(user, p)) {\r\n                        genHtml += `<button class=\"btn btn-soft btn-micro\" onclick=\"abrirModalGeneral('${user}')\">✏️ Editar General</button>`;\r\n                    }\r\n                    genHtml += `</div>`;\r\n                    if (tieneGenAlerta) {\r\n                        genHtml += `<div class=\"nota-block ck-content-render mb-2\" style=\"background:#fffbe6;border-color:#ffe58f;border-left-color:#FAAD14;\">\r\n                            <div class=\"small fw-bold mb-1\" style=\"color:#ad6800;\">⚠️ Alerta General</div>\r\n                            ${genEntry.alerta}\r\n                        </div>`;\r\n                    }\r\n                    if (tieneGenBloq) {\r\n                        genHtml += `<div class=\"nota-block ck-content-render mb-2\" style=\"background:#fff1f0;border-color:#ffa39e;border-left-color:#FF4D4F;\">\r\n                            <div class=\"small fw-bold mb-1\" style=\"color:#cf1322;\">🔴 Bloqueante General</div>\r\n                            ${genEntry.bloqueante}\r\n                        </div>`;\r\n                    }\r\n                    if (tieneGenNota) {\r\n                        genHtml += `<div class=\"nota-block ck-content-render mb-0\">\r\n                            <div class=\"small fw-bold mb-1\" style=\"color:#0050b3;\">📝 Notas</div>\r\n                            ${genEntry.nota}\r\n                        </div>`;\r\n                    }\r\n                    genDiv.innerHTML = genHtml;\r\n                    userBlock.appendChild(genDiv);\r\n                }\r\n\r\n                uData.filter(e => e.tipo === 'Tarea').forEach(t => {\r\n                    if (currentTab === 'gestion' && t.estado === 'Completado') return;\r\n\r\n                    const subTareas = uData.filter(st => st.parentId === t.id);\r\n\r\n                    const allTaskAvances = [];\r\n                    subTareas.forEach(st => {\r\n                        uData.filter(av => av.parentId === st.id && av.estado !== 'Eliminada').forEach(av => allTaskAvances.push(av));\r\n                    });\r\n\r\n                    const avancesEvaluablesTarea = currentTab === 'gestion'\r\n                        ? allTaskAvances.filter(av => av.estado !== 'Completado')\r\n                        : allTaskAvances.filter(av => omitirFiltroFechaPorBloqAlerta ? true : validateDate(av));\r\n\r\n                    const tareaTieneAvanceBloqueado = avancesEvaluablesTarea.some(av => av.estado === 'Detenido' && tieneContenidoHtml(av.bloqueante));\r\n                    const tareaTieneAvanceAlerta    = avancesEvaluablesTarea.some(av => av.estado === 'Detenido' && tieneContenidoHtml(av.alerta));\r\n\r\n                    if (currentTab === 'reporte' && rTaskCond) {\r\n                        if (rTaskCond === 'con_avances_activos') {\r\n                            const tieneActivos = allTaskAvances.some(av => av.estado !== 'Completado' && validateDate(av));\r\n                            if (!tieneActivos) return;\r\n                        } else if (rTaskCond === 'con_avances_terminados') {\r\n                            const tieneCompletados = allTaskAvances.some(av => av.estado === 'Completado' && validateDate(av));\r\n                            if (!tieneCompletados) return;\r\n                        } else if (rTaskCond === 'con_bloqueantes_alertas') {\r\n                            const tieneBloqOAlerta = allTaskAvances.some(av =>\r\n                                av.estado === 'Detenido' && (tieneContenidoHtml(av.bloqueante) || tieneContenidoHtml(av.alerta))\r\n                            );\r\n                            if (!tieneBloqOAlerta) return;\r\n                        } else if (rTaskCond === 'con_notas') {\r\n                            if (!tieneContenidoHtml(notasData[t.id])) return;\r\n                        }\r\n                    }\r\n\r\n                    const tareaMatchSearch = !rSearch ||\r\n                        textoPlano(t.desc).toLowerCase().includes(rSearch) ||\r\n                        (t.descripcionTarea || '').toLowerCase().includes(rSearch);\r\n\r\n                    let hasVisibleSubtask = false;\r\n                    const taskContent = document.createElement('div');\r\n                    taskContent.className = \"subtasks-tree-container\";\r\n\r\n                    subTareas.forEach(st => {\r\n                        const stNombreLimpio = textoPlano(st.desc);\r\n                        const stMatchSearch = !rSearch || tareaMatchSearch || stNombreLimpio.toLowerCase().includes(rSearch);\r\n\r\n                        const allAvsForSt = uData.filter(av => av.parentId === st.id && av.estado !== 'Eliminada');\r\n\r\n                        if (currentTab === 'reporte' && rTaskCond === 'con_bloqueantes_alertas') {\r\n                            const subtareaTieneBloqOAlerta = allAvsForSt.some(avItem =>\r\n                                avItem.estado === 'Detenido' && (tieneContenidoHtml(avItem.bloqueante) || tieneContenidoHtml(avItem.alerta))\r\n                            );\r\n                            if (!subtareaTieneBloqOAlerta) return;\r\n                        }\r\n\r\n                        if (currentTab === 'gestion' && st.estado === 'Completado') return;\r\n                        let avs = uData.filter(av => av.parentId === st.id);\r\n                        if (currentTab === 'gestion') {\r\n                            avs = avs.filter(av => av.estado !== 'Completado' && av.estado !== 'Eliminada');\r\n                        } else {\r\n                            avs = avs.filter(av => av.estado !== 'Eliminada' && (omitirFiltroFechaPorBloqAlerta ? true : validateDate(av)));\r\n\r\n                            if (!rAvEst && rTaskCond === 'con_avances_activos') {\r\n                                avs = avs.filter(av => av.estado !== 'Completado');\r\n                            } else if (!rAvEst && rTaskCond === 'con_avances_terminados') {\r\n                                avs = avs.filter(av => av.estado === 'Completado');\r\n                            }\r\n\r\n                            if (rAvEst) {\r\n                                if (rAvEst === 'ACTIVOS') avs = avs.filter(av => av.estado !== 'Completado');\r\n                                else if (rAvEst === 'Detenido_Alerta') avs = avs.filter(av => av.estado === 'Detenido' && tieneContenidoHtml(av.alerta));\r\n                                else if (rAvEst === 'Detenido_Bloqueante') avs = avs.filter(av => av.estado === 'Detenido' && tieneContenidoHtml(av.bloqueante));\r\n                                else avs = avs.filter(av => av.estado === rAvEst);\r\n                            }\r\n\r\n                            if (rSearch && !stMatchSearch) {\r\n                                avs = avs.filter(av => textoPlano(av.desc).toLowerCase().includes(rSearch));\r\n                            }\r\n\r\n                            avs = avs.slice().sort((a, b) => {\r\n                                const da = a.fechaInicio ? new Date(a.fechaInicio + 'T00:00:00').getTime() : -Infinity;\r\n                                const db = b.fechaInicio ? new Date(b.fechaInicio + 'T00:00:00').getTime() : -Infinity;\r\n                                return db - da;\r\n                            });\r\n                        }\r\n\r\n                        if (currentTab === 'gestion' || avs.length > 0) {\r\n                            hasVisibleSubtask = true; hasVisibleContentForUser = true;\r\n                            const box = document.createElement('div');\r\n                            box.className = \"level-2-box\";\r\n                            const infoColSt = obtenerInfoColorEstado(st.estado, st);\r\n                            box.style.borderLeftColor = infoColSt.hex;\r\n\r\n                            const badgeEstadoSt = st.estado !== 'En proceso'\r\n                                ? ` ${renderBadgeEstadoHtml(st.estado, st)}`\r\n                                : '';\r\n\r\n                            let html = `<div class=\"level-2-title\">\r\n                                <span class=\"d-flex align-items-center flex-wrap gap-2\">\r\n                                    <i class=\"bi bi-folder2 text-secondary\"></i>\r\n                                    <span>${st.desc}</span>\r\n                                    ${badgeEstadoSt}\r\n                                </span>`;\r\n                            if(currentTab === 'gestion') {\r\n                                html += `<div class=\"actions-wrap\">`;\r\n                                if(st.owner === currentUserEmail)\r\n                                    html += `<button class=\"btn btn-soft btn-micro\" onclick=\"edit('${st.id}')\">✏️ Editar</button>`;\r\n                                html += `<button class=\"btn btn-soft-primary btn-micro\" onclick=\"openModal('Avance','${st.id}','')\">+ Actividad</button>`;\r\n                                html += `</div>`;\r\n                            }\r\n                            html += `</div>`;\r\n\r\n                            if(avs.length > 0) {\r\n                                html += `<div class=\"level-3-list\">`;\r\n                                avs.forEach(av => {\r\n                                    const infoColAv = obtenerInfoColorEstado(av.estado, av);\r\n                                    const fechaLabel = av.fechaInicio ? `<span class=\"date-pill\"><i class=\"bi bi-calendar3\"></i> ${av.fechaInicio}</span>` : '';\r\n                                    const estadoLabel = currentTab === 'reporte'\r\n                                        ? ` <span class=\"badge-opt ms-1\" style=\"background:${infoColAv.hex};color:#ffffff;font-size:0.62rem;\">${infoColAv.icon} ${infoColAv.label}</span>`\r\n                                        : '';\r\n                                    const descLimpia = limpiarTextoAttr(av.desc, 40);\r\n\r\n                                    const razonDebajoHtml = renderRazonDetenidoDebajoAvanceHtml(av);\r\n\r\n                                    let badgeAtraso = '';\r\n                                    if (currentTab === 'gestion' && av.estado !== 'Completado' && av.estado !== 'Eliminada') {\r\n                                        const info = calcularInfoAtraso(av);\r\n                                        if (info.enAtraso) {\r\n                                            const bloqueado = !info.puedeJustificar;\r\n                                            const cls = bloqueado ? 'badge-atraso bloqueado' : 'badge-atraso';\r\n                                            const tip = bloqueado\r\n                                                ? `title=\"Ya justificado. Disponible en ${info.diasRestantes} día(s)\"`\r\n                                                : `title=\"Avance sin completar hace ${info.diasAtraso} días. Haz clic para justificar\"`;\r\n                                            const click = bloqueado ? '' : `onclick=\"abrirAtraso('${av.id}','${av.owner}','${descLimpia}')\"`;\r\n                                            badgeAtraso = `<span class=\"${cls}\" ${tip} ${click}>⏰ ${info.diasAtraso}d</span>`;\r\n                                        }\r\n                                    }\r\n\r\n                                    if (currentTab === 'reporte') {\r\n                                        const fIni = av.fechaInicio || '-';\r\n                                        const fFin = av.fechaFin || 'En curso';\r\n                                        html += `<details class=\"level-3-item-details\">\r\n                                            <summary>\r\n                                                <div class=\"w-100\">\r\n                                                    <span class=\"ck-content-render\">${av.desc}${estadoLabel} <em class=\"text-muted ms-1\" style=\"font-size:0.76rem;\">(📅 ${fIni} → ${fFin})</em></span>\r\n                                                    ${razonDebajoHtml}\r\n                                                </div>\r\n                                            </summary>\r\n                                            ${renderAvanceDetalleHtml(av)}\r\n                                        </details>`;\r\n                                    } else {\r\n                                        html += `<div class=\"level-3-item\">\r\n                                            <div class=\"flex-grow-1\">\r\n                                                <span class=\"ck-content-render\">${av.desc}${fechaLabel}${badgeAtraso}</span>\r\n                                                ${razonDebajoHtml}\r\n                                            </div>`;\r\n                                        html += `<div class=\"actions-wrap item-hover-actions\">`;\r\n                                        html += renderBadgeEstadoHtml(av.estado, av);\r\n                                        if(av.owner === currentUserEmail) {\r\n                                            html += `<button class=\"btn btn-soft btn-micro\" onclick=\"edit('${av.id}')\">✏️ Editar</button>`;\r\n                                            html += `<button class=\"btn btn-soft-danger btn-micro\" onclick=\"eliminarAvance('${av.id}','${descLimpia}')\">🗑️ Eliminar</button>`;\r\n                                        }\r\n                                        html += `</div>`;\r\n                                        html += `</div>`;\r\n                                    }\r\n                                });\r\n                                html += `</div>`;\r\n                            }\r\n                            box.innerHTML = html; taskContent.appendChild(box);\r\n                        }\r\n                    });\r\n\r\n                    const hasReportInfo = (!rAvEst && (!rSearch || tareaMatchSearch)) && !!notasData[t.id];\r\n\r\n                    if (currentTab === 'gestion' || hasVisibleSubtask || (currentTab === 'reporte' && hasReportInfo && rTaskCond !== 'con_bloqueantes_alertas')) {\r\n                        const taskCard = document.createElement('div');\r\n                        taskCard.className = \"task-workspace-card\";\r\n\r\n                        const tHeader = document.createElement('div');\r\n                        tHeader.className = \"level-1-header\";\r\n                        const tareaDescLimpia = limpiarTextoAttr(t.desc, 60);\r\n                        const badgeEstadoTarea = (currentTab === 'reporte' || t.estado !== 'En proceso')\r\n                            ? ` <span>${renderBadgeEstadoHtml(t.estado, t)}</span>`\r\n                            : '';\r\n\r\n                        const descTareaHtml = (t.descripcionTarea && t.descripcionTarea.trim())\r\n                            ? `<div class=\"task-context-desc\">${t.descripcionTarea}</div>`\r\n                            : '';\r\n\r\n                        let claseIconoPrioridad = '';\r\n                        let titleIconoPrioridad = 'Tarea sin alertas ni bloqueos activos';\r\n                        if (tareaTieneAvanceBloqueado) {\r\n                            claseIconoPrioridad = 'icon-priority-red';\r\n                            titleIconoPrioridad = '🔴 Prioridad Crítica: Contiene actividad(es) detenida(s) por Bloqueante';\r\n                        } else if (tareaTieneAvanceAlerta) {\r\n                            claseIconoPrioridad = 'icon-priority-yellow';\r\n                            titleIconoPrioridad = '⚠️ Atención: Contiene actividad(es) detenida(s) por Alerta';\r\n                        }\r\n\r\n                        let hHtml = `<div class=\"level-1-title-wrap\">\r\n                            <span class=\"task-icon-box ${claseIconoPrioridad}\" title=\"${titleIconoPrioridad}\"><i class=\"bi bi-layers-fill\"></i></span>\r\n                            <div>\r\n                                <div class=\"d-flex align-items-center flex-wrap gap-2\">\r\n                                    <span>${t.desc}</span>\r\n                                    ${badgeEstadoTarea}\r\n                                </div>\r\n                                ${descTareaHtml}\r\n                            </div>\r\n                        </div>`;\r\n\r\n                        if(currentTab === 'gestion') {\r\n                            hHtml += `<div class='actions-wrap'>`;\r\n                            if(t.owner === currentUserEmail)\r\n                                hHtml += `<button class=\"btn btn-soft btn-micro\" onclick=\"edit('${t.id}')\">✏️ Editar</button>`;\r\n                            hHtml += `<button class='btn btn-soft btn-micro' onclick=\"abrirNota('${t.id}','${tareaDescLimpia}')\">📝 Notas</button>`;\r\n                            hHtml += `<button class='btn btn-soft-primary btn-micro' onclick=\"openModal('Subtarea','${t.id}','')\">+ Subtarea</button>`;\r\n                            hHtml += `</div>`;\r\n                        }\r\n                        tHeader.innerHTML = hHtml;\r\n\r\n                        const notaWrap = document.createElement('div');\r\n                        if ((currentTab === 'gestion' || currentTab === 'reporte') && notasData[t.id]) {\r\n                            notaWrap.innerHTML = `<div class=\"nota-block ck-content-render\">\r\n                                <div class=\"d-flex justify-content-between align-items-start mb-1\">\r\n                                    <span class=\"small fw-bold\" style=\"color:#0050b3;\">📝 Notas</span>\r\n                                </div>\r\n                                ${notasData[t.id]}\r\n                            </div>`;\r\n                        }\r\n\r\n                        taskCard.appendChild(tHeader);\r\n                        if (notaWrap.innerHTML) taskCard.appendChild(notaWrap);\r\n                        if (taskContent.children.length > 0) taskCard.appendChild(taskContent);\r\n\r\n                        userBlock.appendChild(taskCard);\r\n                        hasVisibleContentForUser = true;\r\n                    }\r\n                });\r\n                if (hasVisibleContentForUser) {\r\n                    const userHeader = document.createElement('div');\r\n                    userHeader.className = \"user-section-header\";\r\n                    userHeader.innerHTML = `\r\n                        <span class=\"user-avatar-badge\">${obtenerInicialesEmail(user)}</span>\r\n                        <span class=\"user-section-title\">Colaborador: ${nombreDeEmail(user)}</span>\r\n                    `;\r\n                    cont.appendChild(userHeader);\r\n                    cont.appendChild(userBlock);\r\n                }\r\n            }\r\n        });\r\n        if (cont.innerHTML === \"\") {\r\n            cont.innerHTML = `<div class='text-center py-5 text-muted bg-white rounded-3 border'>\r\n                <i class=\"bi bi-folder-x d-block mb-2\" style=\"font-size:2rem;opacity:0.5;\"></i>\r\n                Sin información para mostrar con los filtros seleccionados.\r\n            </div>`;\r\n        }\r\n    }\r\n\r\n    function onTipoDetenidoChange() {\r\n        const tipoDet = document.getElementById('fTipoDetenido').value;\r\n        const wrapBox = document.getElementById('fCamposDetenidoAvance');\r\n        const lbl     = document.getElementById('fRazonDetenidoLabel');\r\n        if (tipoDet === 'Bloqueante') {\r\n            wrapBox.style.background  = '#FFF1F0';\r\n            wrapBox.style.borderColor = '#FFA39E';\r\n            lbl.innerHTML = `🔴 Razón del Bloqueante <span class=\"text-danger\">*</span>`;\r\n        } else {\r\n            wrapBox.style.background  = '#FFFBEB';\r\n            wrapBox.style.borderColor = '#FDE68A';\r\n            lbl.innerHTML = `⚠️ Razón de la Alerta <span class=\"text-danger\">*</span>`;\r\n        }\r\n    }\r\n\r\n    function onEstadoChange() {\r\n        const est            = document.getElementById('fEst').value;\r\n        const tipo           = document.getElementById('fType').value;\r\n        const camposDetenido = document.getElementById('fCamposDetenidoAvance');\r\n\r\n        if (tipo === 'Avance') {\r\n            if (est === 'Detenido') {\r\n                camposDetenido.style.display = 'block';\r\n                onTipoDetenidoChange();\r\n            } else {\r\n                camposDetenido.style.display = 'none';\r\n                document.getElementById('fTipoDetenido').value = '';\r\n                document.getElementById('fRazonDetenido').value = '';\r\n            }\r\n\r\n            const sinEnt = document.getElementById('fSinEntregable').checked;\r\n            const reqSpan = document.getElementById('fEvidenciaReq');\r\n            const reqEntregableSpan = document.getElementById('fEntregableReq');\r\n            if (sinEnt) {\r\n                reqSpan.style.display = 'none';\r\n                reqEntregableSpan.style.display = 'none';\r\n            } else {\r\n                reqSpan.style.display = (est === 'Completado') ? 'inline' : 'none';\r\n                reqEntregableSpan.style.display = (est === 'Completado') ? 'inline' : 'none';\r\n            }\r\n        } else {\r\n            camposDetenido.style.display = 'none';\r\n        }\r\n    }\r\n\r\n    function onSinEntregableChange() {\r\n        const checked = document.getElementById('fSinEntregable').checked;\r\n        document.getElementById('fCampoObservaciones').style.display = checked ? 'block' : 'none';\r\n        document.getElementById('fEvidencia').disabled = checked;\r\n        document.getElementById('fEntregable').disabled = checked;\r\n        if (checked) {\r\n            document.getElementById('fEvidencia').value = '';\r\n            document.getElementById('fEntregable').value = '';\r\n            document.getElementById('fEvidenciaReq').style.display = 'none';\r\n            document.getElementById('fEntregableReq').style.display = 'none';\r\n        } else {\r\n            document.getElementById('fEvidencia').disabled = false;\r\n            document.getElementById('fEntregable').disabled = false;\r\n            onEstadoChange();\r\n        }\r\n    }\r\n\r\n    function openModal(t, pId, id, de='', fI='', fF='', es='En proceso', owner='', pProj='', alerta='', bloqueante='', categoria='', jira='', msd='', espTecnica='', espFuncional='', evidencia='', sinEntregable=false, observaciones='', entregable='', interno=false, descripcionTarea='') {\r\n        const isEdit = id !== '';\r\n        const typeLabel = { 'Tarea': 'Tarea', 'Subtarea': 'Subtarea', 'Avance': 'Actividad' };\r\n        const label = typeLabel[t] || t;\r\n\r\n        document.getElementById('fModalTitle').innerText = isEdit ? `Modificar ${label}` : `Nueva ${label}`;\r\n        document.getElementById('fModalSubtitle').innerText = isEdit ? `Estás editando una ${label.toLowerCase()} existente` : `Completa los datos para registrar la nueva ${label.toLowerCase()}`;\r\n        document.getElementById('fModalBtn').innerText = isEdit ? `GUARDAR CAMBIOS` : `REGISTRAR ${label.toUpperCase()}`;\r\n\r\n        document.getElementById('fDescLabel').innerHTML = t === 'Tarea'\r\n            ? `Título <span class=\"text-danger\">*</span>`\r\n            : `Descripción <span class=\"text-danger\">*</span>`;\r\n        document.getElementById('fCampoDescripcionTarea').style.display = t === 'Tarea' ? 'block' : 'none';\r\n        document.getElementById('fDescTarea').value = t === 'Tarea' ? (descripcionTarea || '') : '';\r\n\r\n        document.getElementById('fId').value = id;\r\n        document.getElementById('fType').value = t;\r\n        document.getElementById('fParent').value = pId;\r\n        if (ckEditor) ckEditor.setData(de);\r\n        else window._pendingCkData = de;\r\n        const fechaInicio = fI || new Date().toISOString().split('T')[0];\r\n        document.getElementById('fIn').value = fechaInicio;\r\n        document.getElementById('fInLabel').innerText = fechaInicio;\r\n        document.getElementById('fFi').value = fF;\r\n        document.getElementById('fEst').value = es;\r\n        document.getElementById('fProj').value = pProj || document.getElementById('projSelect').value;\r\n\r\n        if (t === 'Avance' && es === 'Detenido') {\r\n            if (bloqueante && String(bloqueante).trim()) {\r\n                document.getElementById('fTipoDetenido').value  = 'Bloqueante';\r\n                document.getElementById('fRazonDetenido').value = bloqueante;\r\n            } else if (alerta && String(alerta).trim()) {\r\n                document.getElementById('fTipoDetenido').value  = 'Alerta';\r\n                document.getElementById('fRazonDetenido').value = alerta;\r\n            } else {\r\n                document.getElementById('fTipoDetenido').value  = '';\r\n                document.getElementById('fRazonDetenido').value = '';\r\n            }\r\n        } else {\r\n            document.getElementById('fTipoDetenido').value  = '';\r\n            document.getElementById('fRazonDetenido').value = '';\r\n        }\r\n\r\n        const camposSubtareaExtra = document.getElementById('fCamposSubtareaExtra');\r\n        camposSubtareaExtra.style.display = t === 'Subtarea' ? 'block' : 'none';\r\n        document.getElementById('fJira').value         = jira;\r\n        document.getElementById('fMsd').value          = msd;\r\n        document.getElementById('fEspTecnica').value   = espTecnica;\r\n        document.getElementById('fEspFuncional').value = espFuncional;\r\n\r\n        const camposCat = document.getElementById('fCampoCategoria');\r\n        camposCat.style.display = t === 'Avance' ? 'block' : 'none';\r\n\r\n        const camposAvance = document.getElementById('fCamposAvance');\r\n        camposAvance.style.display = t === 'Avance' ? 'block' : 'none';\r\n        if (t === 'Avance') {\r\n            document.getElementById('fEvidencia').value        = evidencia;\r\n            document.getElementById('fEntregable').value       = entregable;\r\n            document.getElementById('fSinEntregable').checked  = sinEntregable;\r\n            document.getElementById('fInterno').checked        = interno;\r\n            document.getElementById('fObservaciones').value    = observaciones;\r\n            document.getElementById('fCampoObservaciones').style.display = sinEntregable ? 'block' : 'none';\r\n            document.getElementById('fEvidencia').disabled     = sinEntregable;\r\n            document.getElementById('fEntregable').disabled    = sinEntregable;\r\n        } else {\r\n            document.getElementById('fEvidencia').value        = '';\r\n            document.getElementById('fEntregable').value       = '';\r\n            document.getElementById('fSinEntregable').checked  = false;\r\n            document.getElementById('fInterno').checked        = false;\r\n            document.getElementById('fObservaciones').value    = '';\r\n            document.getElementById('fCampoObservaciones').style.display = 'none';\r\n        }\r\n\r\n        onEstadoChange();\r\n\r\n        const sel = document.getElementById('fCategoria');\r\n        sel.innerHTML = '<option value=\"\">-- Selecciona una categoría --</option>';\r\n        categorias.forEach(c => {\r\n            const opt = document.createElement('option');\r\n            opt.value = c.nombre; opt.text = c.nombre;\r\n            if (c.nombre === categoria) opt.selected = true;\r\n            sel.appendChild(opt);\r\n        });\r\n        if (window.$) {\r\n            $('#fCategoria').select2({ dropdownParent: $('#entryModal'), placeholder: 'Escribe para buscar...', allowClear: true, width: '100%' });\r\n            $('#fCategoria').val(categoria || '').trigger('change');\r\n        }\r\n\r\n        const selOwner = document.getElementById('fOwner');\r\n        const targetOwner = owner || (document.getElementById('userSelect').value === \"TODOS\" ? currentUserEmail : document.getElementById('userSelect').value);\r\n        if (targetOwner && !Array.from(selOwner.options).some(o => o.value === targetOwner)) {\r\n            selOwner.add(new Option(nombreDeEmail(targetOwner), targetOwner));\r\n        }\r\n        if (esLiderProyectoActual(pProj)) {\r\n            selOwner.disabled = false;\r\n            selOwner.value = targetOwner;\r\n        } else {\r\n            selOwner.value = currentUserEmail;\r\n            selOwner.disabled = true;\r\n        }\r\n        mEntry.show();\r\n    }\r\n\r\n    function edit(id) {\r\n        const it = rawData.find(e => e.id === id);\r\n        if (it) openModal(\r\n            it.tipo, it.parentId, it.id, it.desc, it.fechaInicio, it.fechaFin, it.estado,\r\n            it.owner, it.projectId, it.alerta||'', it.bloqueante||'', it.categoria||'',\r\n            it.jira||'', it.msd||'', it.espTecnica||'', it.espFuncional||'',\r\n            it.evidencia||'', it.sinEntregable||false, it.observaciones||'',\r\n            it.entregable||'', it.interno||false, it.descripcionTarea||''\r\n        );\r\n    }\r\n\r\n    function save() {\r\n        const fFi        = document.getElementById('fFi').value;\r\n        const fEst       = document.getElementById('fEst').value;\r\n        const fTipo      = document.getElementById('fType').value;\r\n        const sinEnt     = fTipo === 'Avance' ? document.getElementById('fSinEntregable').checked : false;\r\n        const interno    = fTipo === 'Avance' ? document.getElementById('fInterno').checked : false;\r\n        const evidencia  = fTipo === 'Avance' ? document.getElementById('fEvidencia').value.trim() : '';\r\n        const entregable = fTipo === 'Avance' ? document.getElementById('fEntregable').value.trim() : '';\r\n        const observaciones = fTipo === 'Avance' ? document.getElementById('fObservaciones').value.trim() : '';\r\n        const descPrincipal = ckEditor ? ckEditor.getData().trim() : document.getElementById('fDesc').value.trim();\r\n        const descTareaVal  = fTipo === 'Tarea' ? document.getElementById('fDescTarea').value.trim() : '';\r\n\r\n        if (!tieneContenidoHtml(descPrincipal)) {\r\n            alert(fTipo === 'Tarea' ? \"⚠️ El Título de la tarea es obligatorio.\" : \"⚠️ La Descripción es obligatoria.\");\r\n            return;\r\n        }\r\n\r\n        if (fTipo === 'Tarea' && !descTareaVal) {\r\n            alert(\"⚠️ El campo 'Descripción Tarea' es obligatorio.\");\r\n            document.getElementById('fDescTarea').focus();\r\n            return;\r\n        }\r\n\r\n        if (fFi !== \"\" && fEst !== \"Completado\") { alert(\"⚠️ Si hay fecha de fin, el estado debe ser 'Completado'.\"); return; }\r\n        if (fEst === \"Completado\" && fFi === \"\") { alert(\"⚠️ Si el estado es 'Completado', la fecha de fin es obligatoria.\"); return; }\r\n\r\n        const fId = document.getElementById('fId').value;\r\n        if (fId && fEst === 'Completado' && (fTipo === 'Tarea' || fTipo === 'Subtarea')) {\r\n            const hijosAbiertos = rawData.filter(e =>\r\n                e.parentId === fId && e.estado !== 'Completado' && e.estado !== 'Eliminada'\r\n            );\r\n            if (hijosAbiertos.length > 0) {\r\n                const tipoHijo = fTipo === 'Tarea' ? 'subtarea(s)' : 'avance(s)/actividad(es)';\r\n                const detalle = hijosAbiertos\r\n                    .map(h => '• ' + String(h.desc || '').replace(/<[^>]*>/g, '').trim().substring(0, 60))\r\n                    .join('\\n');\r\n                alert(`⚠️ No puedes marcar esta ${fTipo.toLowerCase()} como 'Completado'.\\n\\nTiene ${hijosAbiertos.length} ${tipoHijo} sin completar:\\n${detalle}`);\r\n                return;\r\n            }\r\n        }\r\n\r\n        let alertaVal = '';\r\n        let bloqueanteVal = '';\r\n        if (fTipo === 'Avance' && fEst === 'Detenido') {\r\n            const tipoDet  = document.getElementById('fTipoDetenido').value;\r\n            const razonDet = document.getElementById('fRazonDetenido').value.trim();\r\n            if (!tipoDet) {\r\n                alert(\"⚠️ Debes indicar si la detención corresponde a una Alerta o a un Bloqueante.\");\r\n                document.getElementById('fTipoDetenido').focus();\r\n                return;\r\n            }\r\n            if (!razonDet) {\r\n                alert(\"⚠️ Debes ingresar la justificación/razón por la cual la actividad está Detenida.\");\r\n                document.getElementById('fRazonDetenido').focus();\r\n                return;\r\n            }\r\n            if (tipoDet === 'Alerta') {\r\n                alertaVal     = razonDet;\r\n                bloqueanteVal = '';\r\n            } else {\r\n                alertaVal     = '';\r\n                bloqueanteVal = razonDet;\r\n            }\r\n        }\r\n\r\n        if (fTipo === 'Avance' && fEst === 'Completado') {\r\n            if (sinEnt) {\r\n                if (!observaciones) {\r\n                    alert(\"⚠️ Marcaste 'Sin Entregable'. Debes ingresar una Observación para justificarlo.\");\r\n                    document.getElementById('fObservaciones').focus();\r\n                    return;\r\n                }\r\n            } else {\r\n                if (!evidencia) {\r\n                    alert(\"⚠️ Para completar una actividad debes ingresar la Evidencia.\");\r\n                    document.getElementById('fEvidencia').focus();\r\n                    return;\r\n                }\r\n                if (!entregable) {\r\n                    alert(\"⚠️ Para completar una actividad debes ingresar el Entregable.\");\r\n                    document.getElementById('fEntregable').focus();\r\n                    return;\r\n                }\r\n            }\r\n        }\r\n        const cat = (window.$ ? $('#fCategoria').val() : document.getElementById('fCategoria').value) || '';\r\n        if (fTipo === 'Avance' && !cat) {\r\n            alert(\"⚠️ La categoría es obligatoria.\");\r\n            document.getElementById('fCategoria').focus();\r\n            return;\r\n        }\r\n\r\n        showL(true);\r\n        const data = {\r\n            userOwner:        document.getElementById('fOwner').value,\r\n            projectId:        document.getElementById('fProj').value,\r\n            id:               document.getElementById('fId').value,\r\n            tipo:             fTipo,\r\n            parentId:         document.getElementById('fParent').value,\r\n            desc:             descPrincipal,\r\n            fechaInicio:      document.getElementById('fIn').value,\r\n            fechaFin:         fFi,\r\n            estado:           fEst,\r\n            alerta:           alertaVal,\r\n            bloqueante:       bloqueanteVal,\r\n            categoria:        cat,\r\n            jira:             fTipo === 'Subtarea' ? document.getElementById('fJira').value.trim() : '',\r\n            msd:              fTipo === 'Subtarea' ? document.getElementById('fMsd').value.trim() : '',\r\n            espTecnica:       fTipo === 'Subtarea' ? document.getElementById('fEspTecnica').value.trim() : '',\r\n            espFuncional:     fTipo === 'Subtarea' ? document.getElementById('fEspFuncional').value.trim() : '',\r\n            evidencia:        fTipo === 'Avance' ? evidencia : '',\r\n            entregable:       fTipo === 'Avance' ? entregable : '',\r\n            sinEntregable:    fTipo === 'Avance' ? sinEnt : false,\r\n            interno:          fTipo === 'Avance' ? interno : false,\r\n            observaciones:    fTipo === 'Avance' ? observaciones : '',\r\n            descripcionTarea: fTipo === 'Tarea' ? descTareaVal : ''\r\n        };\r\n        google.script.run\r\n            .withSuccessHandler(() => { mEntry.hide(); loadData(); })\r\n            .withFailureHandler(err => { showL(false); alert('⚠️ ' + err.message); })\r\n            .saveOrUpdateEntry(data);\r\n    }\r\n\r\n    function abrirNota(tareaId, tareaDesc) {\r\n        document.getElementById('nTareaId').value = tareaId;\r\n        document.getElementById('notaSubtitle').innerText = tareaDesc;\r\n        const contenido = notasData[tareaId] || '';\r\n        if (ckNota) ckNota.setData(contenido);\r\n        else window._pendingNotaData = contenido;\r\n        mNota.show();\r\n    }\r\n\r\n    function guardarNota() {\r\n        const tareaId   = document.getElementById('nTareaId').value;\r\n        const contenido = ckNota ? ckNota.getData() : '';\r\n        const tarea     = rawData.find(e => e.id === tareaId);\r\n        if (!tarea) return;\r\n        showL(true);\r\n        google.script.run\r\n            .withSuccessHandler(() => { mNota.hide(); loadData(); })\r\n            .withFailureHandler(err => { showL(false); alert('Error: ' + err.message); })\r\n            .saveNota({ tareaId, owner: tarea.owner, projectId: tarea.projectId, contenido });\r\n    }\r\n\r\n    function eliminarAvance(id, desc) {\r\n        if (!confirm(`¿Eliminar esta actividad?\\n\\n\"${desc}...\"\\n\\nEsta acción es lógica y no se mostrará en la vista de Tareas Activas.`)) return;\r\n        const av = rawData.find(e => e.id === id);\r\n        if (!av) return;\r\n        showL(true);\r\n        const data = {\r\n            userOwner:        av.owner,\r\n            projectId:        av.projectId,\r\n            id:               av.id,\r\n            tipo:             av.tipo,\r\n            parentId:         av.parentId,\r\n            desc:             av.desc,\r\n            fechaInicio:      av.fechaInicio,\r\n            fechaFin:         av.fechaFin,\r\n            estado:           'Eliminada',\r\n            alerta:           '',\r\n            bloqueante:       '',\r\n            categoria:        av.categoria  || '',\r\n            nota:             av.nota       || '',\r\n            evidencia:        av.evidencia  || '',\r\n            entregable:       av.entregable || '',\r\n            sinEntregable:    av.sinEntregable || false,\r\n            interno:          av.interno    || false,\r\n            observaciones:    av.observaciones || '',\r\n            descripcionTarea: av.descripcionTarea || ''\r\n        };\r\n        google.script.run\r\n            .withSuccessHandler(() => loadData())\r\n            .withFailureHandler(err => { showL(false); alert('Error: ' + err.message); })\r\n            .saveOrUpdateEntry(data);\r\n    }\r\n\r\n    function showL(s) { document.getElementById('loading').style.display = s ? 'flex' : 'none'; }\r\n\r\n    // ══════════════════════════════════════════════════\r\n    //  ATRASO DE AVANCES — lógica de 7 días\r\n    // ══════════════════════════════════════════════════\r\n    function parsearHistorialAtraso(observaciones) {\r\n        if (!observaciones || !observaciones.trim()) return [];\r\n        return observaciones.split('homoplato')\r\n            .map(e => e.trim())\r\n            .filter(e => e)\r\n            .map(e => {\r\n                const m = e.match(/^\\[(\\d{4}-\\d{2}-\\d{2})\\]::([\\s\\S]*)$/);\r\n                return m ? { fecha: m[1], texto: m[2].trim() } : null;\r\n            })\r\n            .filter(Boolean);\r\n    }\r\n\r\n    function separarObservacionesYAtrasos(observaciones) {\r\n        if (!observaciones || !observaciones.trim()) return { textoLibre: '', atrasos: [] };\r\n\r\n        const partes = observaciones.split('homoplato')\r\n            .map(e => e.trim())\r\n            .filter(Boolean);\r\n\r\n        const atrasos = [];\r\n        const libres = [];\r\n\r\n        partes.forEach(parte => {\r\n            const m = parte.match(/^\\[(\\d{4}-\\d{2}-\\d{2})\\]::([\\s\\S]*)$/);\r\n            if (m) atrasos.push({ fecha: m[1], texto: m[2].trim() });\r\n            else libres.push(parte);\r\n        });\r\n\r\n        return {\r\n            textoLibre: libres.join('<br>'),\r\n            atrasos: atrasos\r\n        };\r\n    }\r\n\r\n    function diasEntre(fechaStr1, fechaStr2) {\r\n        const d1 = new Date(fechaStr1 + 'T00:00:00');\r\n        const d2 = new Date(fechaStr2 + 'T00:00:00');\r\n        return Math.floor((d2 - d1) / 86400000);\r\n    }\r\n\r\n    function calcularInfoAtraso(av) {\r\n        if (av.estado === 'Completado' || av.estado === 'Eliminada') {\r\n            return { enAtraso: false };\r\n        }\r\n        if (!av.fechaInicio) return { enAtraso: false };\r\n\r\n        const hoy = new Date().toISOString().split('T')[0];\r\n        const historial = parsearHistorialAtraso(av.observaciones);\r\n        const ultimaFechaRef = historial.length > 0\r\n            ? historial[historial.length - 1].fecha\r\n            : av.fechaInicio;\r\n\r\n        const diasAtraso = diasEntre(ultimaFechaRef, hoy);\r\n\r\n        if (diasAtraso < 7) return { enAtraso: false };\r\n\r\n        const puedeJustificar = historial.length === 0 || diasEntre(historial[historial.length - 1].fecha, hoy) >= 7;\r\n        const diasRestantes   = puedeJustificar ? 0 : 7 - diasEntre(historial[historial.length - 1].fecha, hoy);\r\n\r\n        return { enAtraso: true, diasAtraso, puedeJustificar, diasRestantes, historial };\r\n    }\r\n\r\n    function abrirAtraso(avanceId, owner, desc) {\r\n        const av = rawData.find(e => e.id === avanceId);\r\n        if (!av) return;\r\n        const info = calcularInfoAtraso(av);\r\n\r\n        document.getElementById('atrasoAvanceId').value = avanceId;\r\n        document.getElementById('atrasoOwner').value    = owner;\r\n        document.getElementById('atrasoSubtitle').innerText = desc;\r\n        document.getElementById('atrasoTexto').value    = '';\r\n        document.getElementById('atrasoBloqueoMsg').style.display = 'none';\r\n\r\n        const histEl = document.getElementById('atrasoHistorial');\r\n        if (info.historial && info.historial.length > 0) {\r\n            histEl.innerHTML = `<div class=\"small fw-bold text-muted mb-2\">📋 Justificaciones anteriores</div>` +\r\n                info.historial.map(h =>\r\n                    `<div class=\"hist-atraso-item\"><div class=\"hist-atraso-fecha\">${h.fecha}</div><div>${h.texto}</div></div>`\r\n                ).join('');\r\n        } else {\r\n            histEl.innerHTML = '';\r\n        }\r\n\r\n        const formEl = document.getElementById('atrasoFormSection');\r\n        const bloqEl = document.getElementById('atrasoBloqueoMsg');\r\n\r\n        if (!info.puedeJustificar) {\r\n            formEl.style.display = 'none';\r\n            bloqEl.style.display = 'block';\r\n            bloqEl.innerHTML = `⏳ Ya registraste una justificación. Podrás ingresar una nueva en <strong>${info.diasRestantes}</strong> día(s).`;\r\n        } else {\r\n            formEl.style.display = 'block';\r\n            bloqEl.style.display = 'none';\r\n        }\r\n\r\n        mAtraso.show();\r\n    }\r\n\r\n    function guardarAtraso() {\r\n        const avanceId      = document.getElementById('atrasoAvanceId').value;\r\n        const owner         = document.getElementById('atrasoOwner').value;\r\n        const justificacion = document.getElementById('atrasoTexto').value.trim();\r\n        const avance = rawData.find(e => e.id === avanceId);\r\n\r\n        if (!justificacion) {\r\n            alert('⚠️ Debes ingresar una justificación.');\r\n            document.getElementById('atrasoTexto').focus();\r\n            return;\r\n        }\r\n\r\n        showL(true);\r\n        google.script.run\r\n            .withSuccessHandler(() => { mAtraso.hide(); loadData(); })\r\n            .withFailureHandler(err => { showL(false); alert('Error: ' + err.message); })\r\n            .saveAtrasoAvance({ avanceId, owner, projectId: avance?.projectId, justificacion });\r\n    }\r\n\r\n    function formatearItemsSublistaReporte(htmlTexto) {\r\n        const trimmed = String(htmlTexto || '').trim();\r\n        if (!trimmed) return '';\r\n        if (/^<(ul|ol)[\\s>]/i.test(trimmed)) {\r\n            return trimmed;\r\n        }\r\n        return `<ul><li>${trimmed}</li></ul>`;\r\n    }\r\n\r\n    function anexarAlFinalHtmlReporte(htmlOriginal, sufijoHtml) {\r\n        if (!sufijoHtml) return htmlOriginal;\r\n        const str = String(htmlOriginal || '');\r\n        const lastClose = str.lastIndexOf('</');\r\n        return lastClose !== -1\r\n            ? str.slice(0, lastClose) + sufijoHtml + str.slice(lastClose)\r\n            : str + sufijoHtml;\r\n    }\r\n\r\n    // Construye el árbol HTML multinivel: Tarea -> Subtarea -> Actividad -> Alerta/Bloqueante\r\n    function renderArbolJerarquicoABReporte(treeMap, generalesList) {\r\n        let html = '';\r\n        treeMap.forEach(tGroup => {\r\n            let stHtml = '';\r\n            tGroup.subtareas.forEach(stGroup => {\r\n                let innerHtml = '';\r\n                stGroup.actividades.forEach(act => {\r\n                    innerHtml += `<li>${act.desc}${formatearItemsSublistaReporte(act.texto)}</li>`;\r\n                });\r\n                if (innerHtml) {\r\n                    stHtml += `<li><em>${stGroup.nombre}</em><ul>${innerHtml}</ul></li>`;\r\n                }\r\n            });\r\n            if (stHtml) {\r\n                html += `<li><strong>${tGroup.nombre}</strong><ul>${stHtml}</ul></li>`;\r\n            }\r\n        });\r\n\r\n        generalesList.forEach(g => {\r\n            html += `<li><strong>${g.titulo}</strong>${formatearItemsSublistaReporte(g.texto)}</li>`;\r\n        });\r\n\r\n        return html ? `<ul>${html}</ul>` : '';\r\n    }\r\n\r\n    function abrirModalReporte() {\r\n        const selUser = document.getElementById('userSelect').value;\r\n        const targets = (selUser === 'TODOS') ? obtenerColaboradoresProyectoActual() : [selUser];\r\n        const cont    = document.getElementById('reporteContenido');\r\n        cont.innerHTML = '';\r\n\r\n        const alertasTree = new Map();\r\n        const bloqueantesTree = new Map();\r\n        const alertasGen = [], bloqueantesGen = [], notasGen = [];\r\n\r\n        function asegurarNodoSubtarea(treeMap, tareaId, tareaNom, stId, stNom) {\r\n            if (!treeMap.has(tareaId)) {\r\n                treeMap.set(tareaId, { nombre: tareaNom, subtareas: new Map() });\r\n            }\r\n            const tNode = treeMap.get(tareaId);\r\n            if (!tNode.subtareas.has(stId)) {\r\n                tNode.subtareas.set(stId, { nombre: stNom, actividades: [] });\r\n            }\r\n            return tNode.subtareas.get(stId);\r\n        }\r\n\r\n        targets.forEach(user => {\r\n            const uData = rawData.filter(d => (d.owner || '').toLowerCase() === user.toLowerCase());\r\n            if (!uData.length) return;\r\n\r\n            uData.filter(e => e.tipo === 'Tarea' && e.estado !== 'No iniciado').forEach(t => {\r\n                const subTareas = uData.filter(st => st.parentId === t.id && st.estado !== 'No iniciado');\r\n                let tareaHtml = '';\r\n                let tareaTieneAlerta = false;\r\n                let tareaTieneBloq   = false;\r\n                const tNombrePlano   = textoPlano(t.desc);\r\n\r\n                subTareas.forEach(st => {\r\n                    let avs = uData.filter(av => av.parentId === st.id)\r\n                        .filter(av => av.estado !== 'Eliminada' && av.estado !== 'No iniciado' && validateDate(av) && !av.interno);\r\n                    if (!avs.length) return;\r\n\r\n                    const stNombrePlano = textoPlano(st.desc);\r\n\r\n                    const avsHtml = avs.map(av => {\r\n                        const avNombrePlano = textoPlano(av.desc);\r\n                        const avTieneAlerta = av.estado === 'Detenido' && tieneContenidoHtml(av.alerta);\r\n                        const avTieneBloq   = av.estado === 'Detenido' && tieneContenidoHtml(av.bloqueante);\r\n\r\n                        if (avTieneAlerta) {\r\n                            tareaTieneAlerta = true;\r\n                            asegurarNodoSubtarea(alertasTree, t.id, tNombrePlano, st.id, stNombrePlano)\r\n                                .actividades.push({ desc: avNombrePlano, texto: av.alerta });\r\n                        }\r\n                        if (avTieneBloq) {\r\n                            tareaTieneBloq = true;\r\n                            asegurarNodoSubtarea(bloqueantesTree, t.id, tNombrePlano, st.id, stNombrePlano)\r\n                                .actividades.push({ desc: avNombrePlano, texto: av.bloqueante });\r\n                        }\r\n\r\n                        const estadoBadge = av.estado === 'Detenido'\r\n                            ? ' <strong>[Detenido]</strong>'\r\n                            : av.estado === 'Completado'\r\n                            ? ' <strong>[Completado]</strong>'\r\n                            : '';\r\n\r\n                        const descFinal = anexarAlFinalHtmlReporte(av.desc, estadoBadge);\r\n                        return `<li>${descFinal}</li>`;\r\n                    }).join('');\r\n\r\n                    tareaHtml += `<li><span style=\"font-weight:600;\">${stNombrePlano}</span><ul>${avsHtml}</ul></li>`;\r\n                });\r\n\r\n                if (tareaHtml) {\r\n                    let iconosAtencionTarea = '';\r\n                    if (tareaTieneAlerta) iconosAtencionTarea += ' <span title=\"Contiene alertas abajo\">⚠️</span>';\r\n                    if (tareaTieneBloq)   iconosAtencionTarea += ' <span title=\"Contiene bloqueantes abajo\">🔴</span>';\r\n\r\n                    const tituloTareaFinal = anexarAlFinalHtmlReporte(t.desc, iconosAtencionTarea);\r\n                    cont.innerHTML += `<div><p><strong>${tituloTareaFinal}</strong></p><ul>${tareaHtml}</ul></div>`;\r\n                }\r\n            });\r\n\r\n            // Alertas, bloqueantes y notas generales del proyecto\r\n            uData.filter(d => d.tipo === 'General').forEach(g => {\r\n                if (tieneContenidoHtml(g.alerta)) {\r\n                    alertasGen.push({ titulo: 'Alerta General', texto: g.alerta });\r\n                }\r\n                if (tieneContenidoHtml(g.bloqueante)) {\r\n                    bloqueantesGen.push({ titulo: 'Bloqueante General', texto: g.bloqueante });\r\n                }\r\n                if (tieneContenidoHtml(g.nota)) {\r\n                    notasGen.push(g.nota);\r\n                }\r\n            });\r\n        });\r\n\r\n        if (!cont.innerHTML.trim()) {\r\n            cont.innerHTML = '<p style=\"color:#6c757d;text-align:center;padding:20px;\">Sin información de actividades para mostrar con el filtro actual.</p>';\r\n        }\r\n\r\n        const htmlAlertasJerarquico     = renderArbolJerarquicoABReporte(alertasTree, alertasGen);\r\n        const htmlBloqueantesJerarquico = renderArbolJerarquicoABReporte(bloqueantesTree, bloqueantesGen);\r\n\r\n        let seccionAB = `<hr style=\"margin:16px 0;\">`;\r\n        seccionAB += `<p><strong>⚠️ Alertas</strong></p>`;\r\n        seccionAB += htmlAlertasJerarquico ? htmlAlertasJerarquico : `<p>No se reportan alertas.</p>`;\r\n\r\n        seccionAB += `<p><strong>🔴 Bloqueantes</strong></p>`;\r\n        seccionAB += htmlBloqueantesJerarquico ? htmlBloqueantesJerarquico : `<p>No se reportan bloqueantes.</p>`;\r\n\r\n        if (notasGen.length > 0) {\r\n            seccionAB += `<p><strong>📝 Notas</strong></p>`;\r\n            seccionAB += notasGen.map(n => `<div style=\"margin-bottom:8px;\">${n}</div>`).join('');\r\n        }\r\n\r\n        cont.innerHTML += seccionAB;\r\n\r\n        new bootstrap.Modal(document.getElementById('reporteModal')).show();\r\n    }\r\n\r\n    function copiarReporte() {\r\n        const el = document.getElementById('reporteContenido');\r\n        const range = document.createRange();\r\n        range.selectNodeContents(el);\r\n        const sel = window.getSelection();\r\n        sel.removeAllRanges();\r\n        sel.addRange(range);\r\n        document.execCommand('copy');\r\n        sel.removeAllRanges();\r\n        const btn = event.target;\r\n        btn.innerText = '✅ COPIADO';\r\n        setTimeout(() => btn.innerText = '📋 COPIAR TODO', 2000);\r\n    }\r\n\r\n    function goHome() {\r\n        document.getElementById('loading').style.display = 'flex';\r\n        window.location.href = '/';\r\n    }\r\n\r\n    function logout() {\r\n        fetch('/api/auth/logout', { method: 'POST' }).finally(() => { window.location.href = '/login'; });\r\n    }\r\n\nif (document.readyState === 'complete') { setTimeout(window.__optimiaOnLoad_index, 0); } else { window.addEventListener('load', window.__optimiaOnLoad_index); }\n";
